    /// D-012 / EI-21746542925159695. `Action::AttachSuSession` had a consumer
    /// in main.rs but no emitter, so reattach-by-advSessionId was unreachable.
    /// The picker now emits it for a chat whose inventory row reconciles
    /// `Attached`.
    fn chat_summary_for(id: &str) -> crate::agent_chats::AgentChatSummary {
        crate::agent_chats::AgentChatSummary {
            id: id.into(),
            role: "operator".into(),
            feature_id: None,
            su_runtime_class: None,
            continued_from_chat_id: None,
            continued_from_turn_count: None,
            title: Some("session".into()),
            turn_count: 2,
            total_input_tokens: Some(0),
            total_output_tokens: Some(0),
            total_cost_usd_cents: Some(0.0),
            usage_complete: true,
            created_at: "2026-08-29".into(),
            updated_at: "2026-08-29T00:00:00Z".into(),
            archived_at: None,
        }
    }

    fn inventory_row_for(
        id: &str,
        reconciliation: crate::su_session::SuSessionReconciliation,
    ) -> crate::su_session::SuSessionInventoryEntry {
        crate::su_session::SuSessionInventoryEntry {
            agent_chat_id: id.into(),
            adv_session_id: 42,
            backend: crate::su_session::SuSessionBackend::Codex,
            lifecycle: crate::su_session::SuSessionLifecycleState::Ready,
            runtime_generation: 1,
            native_session_id: "rollout-42".into(),
            terminal: false,
            reconciliation,
            cwd: None,
        }
    }

    fn select_session_option(a: &mut App, option_id: &str) -> Action {
        a.open_conversation_picker();
        let idx = a
            .session_picker
            .as_ref()
            .unwrap()
            .options
            .iter()
            .position(|option| option.id == option_id)
            .unwrap();
        a.session_picker.as_mut().unwrap().sel = idx;
        a.commit_session_picker()
    }

    /// pui-chat-first-ux P-010: in the default chat, /resume opens the
    /// conversation picker (in-place attach), never the fleet switcher whose
    /// Enter launches a zellij pane the single-session chat does not have.
    #[test]
    fn chat_first_slash_resume_attaches_the_chosen_conversation_in_place() {
        let mut a = App::new();
        a.chat_first = true;
        a.launch_cwd = Some("/work/app".into());
        a.agent_chat_summaries = vec![chat_summary_for("chat-earlier")];
        let mut earlier = inventory_row_for(
            "chat-earlier",
            crate::su_session::SuSessionReconciliation::EndedArchived,
        );
        earlier.cwd = Some("/work/app".into());
        a.su_session_inventory = vec![earlier];
        let opened = a.run_slash_command("resume");
        assert_eq!(opened, Action::Render);
        assert!(
            a.session_switcher.is_none(),
            "the fleet switcher must not open"
        );
        let picker = a
            .session_picker
            .as_ref()
            .expect("conversation picker opens");
        assert_eq!(picker.axis, crate::session_config::PickerAxis::Conversation);
        let row = picker
            .options
            .iter()
            .find(|option| option.id == "chat:chat-earlier")
            .expect("the earlier conversation is listed");
        assert_eq!(row.label, "session · 2 turns");
        assert_eq!(row.hint.as_deref(), Some("updated 2026-08-29 00:00 UTC"));
        for jargon in ["operator", "Codex", "chat-earlier", "ended", "archived"] {
            assert!(
                !row.label.contains(jargon) && !row.hint.as_deref().unwrap_or("").contains(jargon),
                "{jargon:?} leaked into the /resume row: {row:?}"
            );
        }
        assert!(matches!(
            a.commit_session_picker(),
            Action::AttachSuSession {
                adv_session_id: 42,
                ..
            }
        ));
        assert_eq!(a.agent_chat_id.as_deref(), Some("chat-earlier"));
    }

    /// pui-chat-first-ux P-010: like `claude --resume`, the default chat's
    /// /resume lists only the conversations started in this directory. One
    /// started elsewhere, or whose directory is unknown, stays out; an empty
    /// list says so instead of opening a blank overlay; the workbench keeps
    /// the whole pot inventory.
    #[test]
    fn chat_first_slash_resume_lists_only_this_directorys_conversations() {
        let row_in = |id: &str, cwd: Option<&str>| {
            let mut row = inventory_row_for(
                id,
                crate::su_session::SuSessionReconciliation::EndedArchived,
            );
            row.cwd = cwd.map(str::to_owned);
            row
        };
        let mut a = App::new();
        a.chat_first = true;
        a.launch_cwd = Some("/work/app".into());
        a.agent_chat_summaries = vec![
            chat_summary_for("here"),
            chat_summary_for("other-project"),
            chat_summary_for("unknown-dir"),
        ];
        a.su_session_inventory = vec![
            row_in("here", Some("/work/app/")),
            row_in("other-project", Some("/work/other")),
            row_in("unknown-dir", None),
        ];
        a.agent_chats_loaded_for = Some(a.harness.clone());
        a.run_slash_command("resume");
        let ids: Vec<String> = a
            .session_picker
            .as_ref()
            .expect("picker opens")
            .options
            .iter()
            .map(|option| option.id.clone())
            .collect();
        assert_eq!(ids, vec!["chat:here".to_string()]);

        a.session_picker = None;
        a.launch_cwd = Some("/work/empty".into());
        a.run_slash_command("resume");
        let picker = a.session_picker.as_ref().expect("picker opens");
        assert_eq!(picker.options.len(), 1, "{:?}", picker.options);
        assert!(picker.options[0].disabled);
        assert_eq!(
            picker.options[0].label,
            "No earlier conversations in this directory"
        );
        assert_eq!(a.commit_session_picker(), Action::Render);
        assert!(a.agent_chat_id.is_none(), "the empty row attaches nothing");

        a.session_picker = None;
        a.chat_first = false;
        a.open_conversation_picker();
        assert_eq!(a.session_picker.as_ref().unwrap().options.len(), 3);
    }

    /// P-007 (P-005 review, step 5): /resume opened right after relaunch,
    /// before the Agent Chat list arrived, said "No earlier conversations in
    /// this directory" — a disabled row, so Enter did nothing — for a
    /// directory that had one. Until the list lands it must say it is
    /// loading, and the open picker must gain the row when the list and the
    /// SU inventory (which carries each session's cwd) arrive.
    #[test]
    fn chat_first_slash_resume_says_loading_until_the_list_arrives() {
        let mut a = App::new();
        a.chat_first = true;
        a.launch_cwd = Some("/work/app".into());
        let harness = a.harness.clone();
        let token = a.next_agent_chat_load_token();

        a.run_slash_command("resume");
        let picker = a.session_picker.as_ref().expect("picker opens");
        assert_eq!(picker.options.len(), 1, "{:?}", picker.options);
        assert_eq!(picker.options[0].label, "Loading earlier conversations…");
        assert!(picker.options[0].disabled);
        assert!(
            !picker.options[0].label.contains("No earlier"),
            "an unloaded list must never claim there is nothing"
        );

        // The operator emits the inventory, then the load (agent_chat_load).
        let mut row = inventory_row_for(
            "earlier",
            crate::su_session::SuSessionReconciliation::EndedArchived,
        );
        row.cwd = Some("/work/app".into());
        a.update(Event::SuSessionInventory {
            harness: harness.clone(),
            selected_chat_id: None,
            entries: vec![row],
        });
        a.update(Event::AgentChatLoaded {
            harness: harness.clone(),
            chat_id: None,
            role: "operator".into(),
            load_token: token,
            summaries: vec![chat_summary_for("earlier")],
            messages: Vec::new(),
            owner_turn_ids: Vec::new(),
            approvals: Vec::new(),
        });
        let picker = a.session_picker.as_ref().expect("picker stays open");
        let ids: Vec<&str> = picker.options.iter().map(|o| o.id.as_str()).collect();
        assert_eq!(ids, vec!["chat:earlier"], "{:?}", picker.options);
        assert!(!picker.options[0].disabled);

        // Loaded and genuinely empty for this directory: now it may say so.
        a.session_picker = None;
        a.launch_cwd = Some("/work/empty".into());
        a.run_slash_command("resume");
        assert_eq!(
            a.session_picker.as_ref().unwrap().options[0].label,
            "No earlier conversations in this directory"
        );

        // A different pot has not loaded: it reads as loading again.
        a.session_picker = None;
        a.harness = "another-pot".into();
        a.run_slash_command("resume");
        assert_eq!(
            a.session_picker.as_ref().unwrap().options[0].label,
            "Loading earlier conversations…"
        );
    }

