        assert!(
            !a.chat_details_visible(),
            "chat-first hides details by default"
        );
        let action = a.on_key(KeyCode::Char('o'), KeyModifiers::CONTROL);
        assert!(matches!(action, Action::Render), "got {action:?}");
        assert!(a.chat_details_visible());
