    /// P-010: "On startup, adopt/reattach live local displayable SU sessions by
    /// stable advSessionId". Before this, the ONLY emitter of
    /// `AttachSuSession` was the user-initiated session picker (D-012), so a
    /// restart left a live session unattached until the user went and picked
    /// it — the startup half of the requirement had no code path at all.
    fn backend_row(
        chat_id: &str,
        adv_session_id: i64,
        backend: crate::su_session::SuSessionBackend,
        lifecycle: crate::su_session::SuSessionLifecycleState,
        reconciliation: crate::su_session::SuSessionReconciliation,
    ) -> crate::su_session::SuSessionInventoryEntry {
        crate::su_session::SuSessionInventoryEntry {
            agent_chat_id: chat_id.into(),
            adv_session_id,
            backend,
            lifecycle,
            runtime_generation: 1,
            native_session_id: format!("native-{adv_session_id}"),
            terminal: matches!(
                lifecycle,
                crate::su_session::SuSessionLifecycleState::Ended
                    | crate::su_session::SuSessionLifecycleState::Failed
            ),
            reconciliation,
            cwd: None,
        }
    }

    /// P-010 RESTART JOURNEY — three concurrent backends across a PUI restart.
    ///
    /// The reconciliation this exercises is driven by the DURABLE inventory
    /// (stable advSessionIds + persisted descriptors), not by live processes,
    /// which is what makes a three-backend journey deterministic here at all.
    /// PUI hosts one ACTIVE SU pane plus an inventory, so "concurrent Claude,
    /// Codex and OMP sessions" means all three survive the restart on their
    /// stable ids and each adopts exactly once as the owner moves between them.
    ///
    /// Asserted, in order: (1) a fresh process adopts the selected backend;
    /// (2) switching selection adopts the next backend on ITS OWN advSessionId,
    /// never the previously adopted one; (3) an ended row is preserved in the
    /// inventory for inspection and never respawned; (4) returning to an
    /// already-adopted session emits no second attach; (5) the whole sequence
    /// repeats on a genuinely fresh App, which is what a restart is.
    #[test]
    fn su_restart_journey_adopts_three_concurrent_backends_exactly_once_each() {
        use crate::su_session::SuSessionBackend as B;
        use crate::su_session::SuSessionLifecycleState as L;
        use crate::su_session::SuSessionReconciliation as R;

        // Claude and Codex are live; OMP ended before the restart and must be
        // preserved for inspection rather than adopted or relaunched.
        let fleet = || {
            vec![
                backend_row("chat-claude", 101, B::Claude, L::Running, R::Attached),
                backend_row("chat-codex", 102, B::Codex, L::Ready, R::Attached),
                backend_row("chat-omp", 103, B::Omp, L::Ended, R::EndedArchived),
            ]
        };

        // Selecting a chat and receiving the next inventory frame is exactly
        // what the owner switching panes looks like to the reducer.
        let adopt = |app: &mut App, chat_id: &str| -> Action {
            app.agent_chat_id = Some(chat_id.into());
            app.update(Event::SuSessionInventory {
                harness: app.harness.clone(),
                selected_chat_id: Some(chat_id.into()),
                entries: fleet(),
            })
        };

        for restart in 0..2 {
            let mut app = App::new();

            // (1) the selected backend is adopted on its stable adv id.
            assert_eq!(
                adopt(&mut app, "chat-claude"),
                Action::AttachSuSession {
                    harness: "papercup".into(),
                    chat_id: "chat-claude".into(),
                    adv_session_id: 101,
                    backend: B::Claude,
                },
                "restart {restart}: Claude must be adopted by stable advSessionId"
            );
            // The whole fleet stays visible, not just the adopted pane.
            assert_eq!(app.su_session_inventory.len(), 3);
            assert_eq!(
                app.su_session_inventory
                    .iter()
                    .map(|entry| entry.backend)
                    .collect::<Vec<_>>(),
                vec![B::Claude, B::Codex, B::Omp],
                "restart {restart}: all three backends must survive the restart"
            );

            // (2) switching selection adopts the NEXT backend on its own id.
            assert_eq!(
                adopt(&mut app, "chat-codex"),
                Action::AttachSuSession {
                    harness: "papercup".into(),
                    chat_id: "chat-codex".into(),
                    adv_session_id: 102,
                    backend: B::Codex,
                },
                "restart {restart}: Codex must adopt on 102, never re-adopt 101"
            );

            // (3) the ended OMP session kept its saved native conversation, so
            // selecting it resumes it on its OWN id and backend (P-009 D-008:
            // after P-009 every normal quit ends the engine, so "ended" is no
            // longer "abandoned"). Rows with no native id, FailedOrphaned,
            // Pending and RuntimeReplaced still never adopt
            // (su_inventory_never_adopts_non_attached_or_terminal_rows).
            assert_eq!(
                adopt(&mut app, "chat-omp"),
                Action::AttachSuSession {
                    harness: "papercup".into(),
                    chat_id: "chat-omp".into(),
                    adv_session_id: 103,
                    backend: B::Omp,
                },
                "restart {restart}: an ended session with a saved conversation resumes on 103"
            );
            assert!(app
                .su_session_inventory
                .iter()
                .any(|entry| entry.agent_chat_id == "chat-omp"
                    && entry.reconciliation == R::EndedArchived));

            // (4) returning to an already-adopted session emits no second attach.
            assert_eq!(
                adopt(&mut app, "chat-claude"),
                Action::Render,
                "restart {restart}: re-selecting an adopted session must not duplicate the pane"
            );
            assert_eq!(
                app.su_adopted_sessions.iter().copied().collect::<Vec<_>>(),
                vec![101, 102, 103],
                "restart {restart}: each backend's session was adopted exactly once"
            );
        }
    }

    /// The run loop binds a new chat (`AgentChatBound`) before launch-su returns
    /// its binding, and a real engine starts slowly enough for an inventory
    /// frame to report that chat `Attached` in between. Adopting it then sent a
    /// second launch-su for the session PUI was still creating (measured on the
    /// installed real-Claude greeting journey: launch-su count 2, one engine).
    #[test]
    fn su_inventory_does_not_adopt_the_session_its_own_open_is_creating() {
        use crate::su_session::SuSessionBackend as B;
        use crate::su_session::SuSessionLifecycleState as L;
        use crate::su_session::SuSessionReconciliation as R;
        let opening = |a: &mut App| {
            a.tab = Tab::Operator;
            a.chat_composing = true;
            a.chat_input = "hello".into();
            assert_eq!(
                a.on_key(KeyCode::Enter, KeyModifiers::NONE),
                Action::CheckSessionSetup
            );
            for _ in [1, 2] {
                a.on_key(KeyCode::Enter, KeyModifiers::NONE);
            }
            assert!(matches!(
                a.on_key(KeyCode::Enter, KeyModifiers::NONE),
                Action::OpenSuSession { .. }
            ));
            a.update(Event::AgentChatBound("chat-new".into()));
        };
        let frame = |a: &App| Event::SuSessionInventory {
            harness: a.harness.clone(),
            selected_chat_id: Some("chat-new".into()),
            entries: vec![backend_row(
                "chat-new",
                7,
                B::Claude,
                L::Starting,
                R::Attached,
            )],
        };

        let mut a = setup_app();
        opening(&mut a);
        let inventory = frame(&a);
        assert_eq!(
            a.update(inventory),
            Action::Render,
            "the open in flight owns this session"
        );
        a.update(Event::SuSessionOpened(su_binding()));
        let inventory = frame(&a);
        assert_eq!(
            a.update(inventory),
            Action::Render,
            "a bound pane is never re-attached"
        );

        // A failed open leaves nothing bound, so a live row is adoptable again.
        let mut a = setup_app();
        opening(&mut a);
        a.update(Event::SuSessionError("launch-su refused".into()));
        let inventory = frame(&a);
        assert!(matches!(
            a.update(inventory),
            Action::AttachSuSession {
                adv_session_id: 7,
                ..
            }
        ));
    }

    /// The inventory row must honour the host's non-attachable verdicts, or a
    /// `relaunch`/`wait` session is offered for adoption and a pane attaches to
    /// a runtime the host already reported as absent.
    #[test]
    fn su_inventory_row_honours_a_non_attachable_runtime_verdict() {
        for (action, expected) in [
            (
                "reattach",
                crate::su_session::SuSessionReconciliation::Attached,
            ),
            (
                "relaunch",
                crate::su_session::SuSessionReconciliation::FailedOrphaned,
            ),
            ("wait", crate::su_session::SuSessionReconciliation::Pending),
        ] {
            let snapshot: crate::su_session::SuSessionSnapshot = serde_json::from_value(json!({
                "ok": true,
                "descriptor": {
                    "identity": {"agentChatId":"chat-1", "advSessionId":7, "backend":"claude", "nativeSessionId":"native-1", "ownerId":"su-1", "workspaceId":"ws-1", "harnessSlug":"papercup"},
                    "lifecycle":"running", "runtimeGeneration":1, "role":"su", "carry":"warm", "modes":[],
                    "capabilities": {"commands":{}, "features":{}},
                    "backendExtension": {"backend":"claude", "configDir":null, "configDirSource":null}
                },
                "floorSequence":1, "lastSequence":2, "terminal": false,
                "runtimeReconciliation": {"action": action, "reason": "probe", "stalePid": true}
            }))
            .expect("decode SU snapshot");
            let entry = crate::su_session::SuSessionInventoryEntry::from_snapshot(&snapshot);
            assert_eq!(entry.reconciliation, expected, "action {action}");
            if expected != crate::su_session::SuSessionReconciliation::Attached {
                assert_ne!(
                    entry.reconciliation,
                    crate::su_session::SuSessionReconciliation::Attached,
                    "{action} must not be offered for adoption"
                );
            }
        }
    }

    #[test]
    fn su_inventory_adopts_a_live_session_on_startup() {
        let mut app = App::new();
        app.agent_chat_id = Some("chat-1".into());
        let action = app.update(Event::SuSessionInventory {
            harness: app.harness.clone(),
            selected_chat_id: Some("chat-1".into()),
            entries: vec![inventory_row_for(
                "chat-1",
                crate::su_session::SuSessionReconciliation::Attached,
            )],
        });
        assert_eq!(
            action,
            Action::AttachSuSession {
                harness: "papercup".into(),
                chat_id: "chat-1".into(),
                adv_session_id: 42,
                backend: crate::su_session::SuSessionBackend::Codex,
            }
        );
    }

    /// P-010: "prevent duplicate panes/processes". The inventory refreshes on a
    /// cadence, and the binding does not land in the same tick that adoption is
    /// emitted — so a second frame arriving in that window must NOT emit a
    /// second attach for the same advSessionId.
    #[test]
    fn su_inventory_adoption_fires_at_most_once_per_adv_session_id() {
        let mut app = App::new();
        app.agent_chat_id = Some("chat-1".into());
        let row = inventory_row_for(
            "chat-1",
            crate::su_session::SuSessionReconciliation::Attached,
        );
        let first = app.update(Event::SuSessionInventory {
            harness: app.harness.clone(),
            selected_chat_id: Some("chat-1".into()),
            entries: vec![row.clone()],
        });
        assert!(matches!(first, Action::AttachSuSession { .. }));
        // `su_session` is still None here — the attach task has not bound yet,
        // which is precisely the window the guard set exists to cover.
        assert!(app.su_session.is_none());
        let second = app.update(Event::SuSessionInventory {
            harness: app.harness.clone(),
            selected_chat_id: Some("chat-1".into()),
            entries: vec![row],
        });
        assert_eq!(second, Action::Render, "adoption must not re-fire");
    }

    /// pui-chat-first-ux P-009 / D-008: quitting a PUI ends its engine, so the
    /// restored chat's row is normally `EndedArchived`. Reopening the workbench
    /// resumes it from its transcript, like picking it in Sessions. A row with
    /// no native session id has nothing to resume and stays unadopted.
    #[test]
    fn su_inventory_resumes_the_restored_chat_after_its_engine_ended() {
        let mut ended = inventory_row_for(
            "chat-1",
            crate::su_session::SuSessionReconciliation::EndedArchived,
        );
        ended.lifecycle = crate::su_session::SuSessionLifecycleState::Ended;
        ended.terminal = true;
        let mut app = App::new();
        app.agent_chat_id = Some("chat-1".into());
        let action = app.update(Event::SuSessionInventory {
            harness: app.harness.clone(),
            selected_chat_id: Some("chat-1".into()),
            entries: vec![ended.clone()],
        });
        assert_eq!(
            action,
            Action::AttachSuSession {
                harness: "papercup".into(),
                chat_id: "chat-1".into(),
                adv_session_id: 42,
                backend: crate::su_session::SuSessionBackend::Codex,
            }
        );
        // Only the restored chat resumes; another chat's ended row does not.
        let mut app = App::new();
        app.agent_chat_id = Some("chat-2".into());
        let action = app.update(Event::SuSessionInventory {
            harness: app.harness.clone(),
            selected_chat_id: Some("chat-2".into()),
            entries: vec![ended.clone()],
        });
        assert_eq!(
            action,
            Action::Render,
            "another chat's ended row must not adopt"
        );
        // Nothing native to resume from.
        let mut app = App::new();
        app.agent_chat_id = Some("chat-1".into());
        ended.native_session_id.clear();
        let action = app.update(Event::SuSessionInventory {
            harness: app.harness.clone(),
            selected_chat_id: Some("chat-1".into()),
            entries: vec![ended],
        });
        assert_eq!(
            action,
            Action::Render,
            "an ended row with no native id must not adopt"
        );
    }

    /// P-010: failed rows are "preserved for inspection" and converged to an
    /// explicit state — they must never be respawned. `Attached` asserts a
    /// still-present runtime; an ended row resumes only as above (P-009).
    #[test]
    fn su_inventory_never_adopts_non_attached_or_terminal_rows() {
        for reconciliation in [
            crate::su_session::SuSessionReconciliation::FailedOrphaned,
            crate::su_session::SuSessionReconciliation::Pending,
            crate::su_session::SuSessionReconciliation::RuntimeReplaced,
        ] {
            let mut app = App::new();
            app.agent_chat_id = Some("chat-1".into());
            let action = app.update(Event::SuSessionInventory {
                harness: app.harness.clone(),
                selected_chat_id: Some("chat-1".into()),
                entries: vec![inventory_row_for("chat-1", reconciliation)],
            });
            assert_eq!(action, Action::Render, "{reconciliation:?} must not adopt");
        }

        // An `Attached` row that is nonetheless terminal is also not adoptable.
        let mut app = App::new();
        app.agent_chat_id = Some("chat-1".into());
        let mut terminal_row = inventory_row_for(
            "chat-1",
            crate::su_session::SuSessionReconciliation::Attached,
        );
        terminal_row.terminal = true;
        let action = app.update(Event::SuSessionInventory {
            harness: app.harness.clone(),
            selected_chat_id: Some("chat-1".into()),
            entries: vec![terminal_row],
        });
        assert_eq!(action, Action::Render, "terminal row must not adopt");
    }

    /// P-010 duplicate-attach interlock across BOTH emitters.
    ///
    /// This is the regression the two emitters create together, and neither
    /// one's own tests can see it. The picker (D-012) calls
    /// `reset_agent_chat_binding()` before returning its attach, which clears
    /// `su_session`; an inventory frame arriving before the binding lands then
    /// satisfies adoption's `su_session.is_none()` guard and would spawn a
    /// SECOND process for the same advSessionId. The picker therefore records
    /// into `su_adopted_sessions` too, making that set the single authority on
    /// "an attach has already been issued".
    #[test]
    fn picker_attach_suppresses_a_following_inventory_adoption() {
        let mut app = App::new();
        app.agent_chat_summaries = vec![crate::agent_chats::AgentChatSummary {
            id: "chat-1".into(),
            role: "worker".into(),
            feature_id: None,
            su_runtime_class: None,
            continued_from_chat_id: None,
            continued_from_turn_count: None,
            title: Some("Live SU session".into()),
            turn_count: 1,
            total_input_tokens: Some(1),
            total_output_tokens: Some(1),
            total_cost_usd_cents: Some(0.0),
            usage_complete: true,
            created_at: "2026-08-29".into(),
            updated_at: "2026-08-29T00:00:00Z".into(),
            archived_at: None,
        }];
        app.su_session_inventory = vec![inventory_row_for(
            "chat-1",
            crate::su_session::SuSessionReconciliation::Attached,
        )];
        app.open_conversation_picker();
        let idx = app
            .session_picker
            .as_ref()
            .unwrap()
            .options
            .iter()
            .position(|option| option.id == "chat:chat-1")
            .unwrap();
        app.session_picker.as_mut().unwrap().sel = idx;
        assert!(matches!(
            app.commit_session_picker(),
            Action::AttachSuSession {
                adv_session_id: 42,
                ..
            }
        ));
        assert!(
            app.su_session.is_none(),
            "picker clears the binding, which is what opens the double-attach window"
        );

        let action = app.update(Event::SuSessionInventory {
            harness: app.harness.clone(),
            selected_chat_id: Some("chat-1".into()),
            entries: vec![inventory_row_for(
                "chat-1",
                crate::su_session::SuSessionReconciliation::Attached,
            )],
        });
        assert_eq!(
            action,
            Action::Render,
            "a picker-initiated attach must suppress startup adoption for the same advSessionId"
        );
    }

    #[test]
    fn bee_panes_append_grouped_by_kind_and_dedup_by_owner() {
        let mut a = App::new();
        a.hive_agent_tabs = true;
        a.dock_agent_panes = true;
        // Roster interleaves planner/bee/planner/bee — the batch must group.
        a.set_roster(vec![
            fleet_bee("p-1", "planner"),
            fleet_bee("b-1", "bee"),
            fleet_bee("p-2", "planner"),
            fleet_bee("b-2", "bee"),
        ]);
        let specs = a.bee_panes_to_open();
        let titles: Vec<&str> = specs
            .iter()
            .map(|s| s.title.as_deref().unwrap_or(""))
            .collect();
        // One pane per agent (owner ask 2026-06-11: bees do NOT get a per-bee
        // wake pane — they review via the fleet-wide board; the queen's inline
        // split lives in the dock KDL). 4 agents ⇒ 4 specs.
        assert_eq!(specs.len(), 4);
        // Bees (rank 2) before planners (rank 3); roster order within a group.
        assert!(
            titles[0].starts_with("🍵") && titles[1].starts_with("🍵"),
            "{titles:?}"
        );
        assert!(
            titles[2].starts_with("📋") && titles[3].starts_with("📋"),
            "{titles:?}"
        );
        // The dedup set records OWNER ids (not argv[2], which is a session id for
        // a flag-on claude --resume bee) — a re-refresh opens nothing.
        for o in ["p-1", "b-1", "p-2", "b-2"] {
            assert!(a.paned_bees.contains(o), "owner {o} not recorded");
        }
        assert!(
            a.bee_panes_to_open().is_empty(),
            "second refresh must dedup"
        );
    }

    #[test]
    fn bee_pane_title_prefers_role_over_agent() {
        let mut a = App::new();
        a.hive_agent_tabs = true;
        a.dock_agent_panes = true;
        // A role-carrying WORKER row. (The singleton roles — mug/kettle/papercup —
        // are no longer paned at all, so the title path is exercised on a cup.)
        let mut cup = fleet_bee("s-123-abc", "cup");
        cup.role = Some("cup".into());
        a.set_roster(vec![cup, fleet_bee("b-1", "bee")]);
        let titles: Vec<String> = a
            .bee_panes_to_open()
            .iter()
            .map(|s| s.title.clone().unwrap_or_default())
            .collect();
        // A role-carrying row titles with the ROLE — the agent name ("claude")
        // identifies nothing; role-less rows keep the agent fallback.
        assert!(titles.iter().any(|t| t.contains("cup · ")), "{titles:?}");
        assert!(titles.iter().any(|t| t.contains("claude · ")), "{titles:?}");
    }

    #[test]
    fn singleton_roles_never_reactively_pane_only_cups_do() {
        // Owner ask 2026-07-13 ("all the mug turns should happen in the single mug
        // pane ... same for kettle ... same for papercup"): mug/kettle/papercup each
        // own ONE fixed pane in the dock KDL, and that pane already rolls forward to
        // the role's newest wake by itself. Every wake is a NEW adv_session with a
        // NEW owner id, so without this gate the owner_id dedup reads each turn as a
        // brand-new bee and stacks another dead `claude --resume` pane behind the
        // live one (24h of real roster data: kettle 122 sessions, papercup 81,
        // mug 56). The reactive stack is for WORKERS only.
        let mut a = App::new();
        a.hive_agent_tabs = true;
        a.dock_agent_panes = true;
        let role_row = |owner: &str, role: &str| {
            let mut r = fleet_bee(owner, role);
            r.role = Some(role.into());
            r
        };
        // The REAL backend shape for a papercup row: classifyAgentPane has no
        // `papercup` arm (it matches operator/oracle), so the role falls through to
        // the default and the row arrives stamped agentPaneKind="cup" — a WORKER.
        // Keying the gate on that stamped kind would keep paning the very role the
        // owner named; we key on `role`, so this row is still excluded.
        let mut papercup = fleet_bee("s-1783922650850", "cup");
        papercup.role = Some("papercup".into());

        a.set_roster(vec![
            role_row("s-1783921649457", "kettle"),
            role_row("s-1783922048712", "kettle"),
            role_row("s-1783922650849", "mug"),
            papercup,
            // The hidden heavy half of the ONE Papercup identity — deliberately
            // paneless (WI-4485): woken over coord, never takes pane input.
            role_row("s-1783922650851", "papercup-deep"),
            role_row("c-1", "cup"),
        ]);

        let titles: Vec<String> = a
            .bee_panes_to_open()
            .iter()
            .map(|s| s.title.clone().unwrap_or_default())
            .collect();
        // Six live fleet-spawn rows in, exactly ONE pane out: the worker cup.
        assert_eq!(titles.len(), 1, "{titles:?}");
        assert!(titles[0].contains("cup · "), "{titles:?}");
        // The singletons must not be recorded as paned either — a row that is
        // never paned must not occupy the dedup set (that would only mask it).
        for o in [
            "s-1783921649457",
            "s-1783922048712",
            "s-1783922650849",
            "s-1783922650850",
            "s-1783922650851",
        ] {
            assert!(!a.paned_bees.contains(o), "singleton {o} must not be paned");
        }
        assert!(a.paned_bees.contains("c-1"));
    }

    #[test]
    fn owner_scoped_wake_pane_exits_only_when_bee_gone_and_queue_drained() {
        let mut a = App::new();
        a.wake_filter = WakeFilter::Owner("b-1".into());
        a.update(Event::WakeBoard {
            result: Ok((
                vec![board_group("b-1", vec![pending_wake(7, "boot")])],
                None,
            )),
        });
        let bee = fleet_bee("b-1", "bee");
        // Present → no exit, misses reset.
        a.update(Event::Roster {
            active: vec![bee.clone()],
            pending: vec![],
        });
        assert!(!a.wake_pane_should_exit());
        // Gone twice → still NO exit: the queue holds a reviewable wake.
        a.update(Event::Roster {
            active: vec![],
            pending: vec![],
        });
        a.update(Event::Roster {
            active: vec![],
            pending: vec![],
        });
        assert_eq!(a.wake_owner_misses, 2);
        assert!(
            !a.wake_pane_should_exit(),
            "drain gate: staged wakes keep the pane"
        );
        // Queue drains → NOW it exits.
        a.update(Event::WakeBoard {
            result: Ok((vec![], None)),
        });
        assert!(a.wake_pane_should_exit());
        // A returning bee resets the misses (churn tolerance).
        a.update(Event::Roster {
            active: vec![bee],
            pending: vec![],
        });
        assert!(!a.wake_pane_should_exit());
        assert_eq!(a.wake_owner_misses, 0);
        // The static panes never self-exit, drained or not.
        let mut q = App::new();
        q.wake_filter = WakeFilter::Queen;
        q.update(Event::WakeBoard {
            result: Ok((vec![], None)),
        });
        q.update(Event::Roster {
            active: vec![],
            pending: vec![],
        });
        q.update(Event::Roster {
            active: vec![],
            pending: vec![],
        });
        assert!(!q.wake_pane_should_exit());
    }

