    #[test]
    fn tui_set_tab_event_routes_non_lazy_tab_entry_actions() {
        let cases = [
            // Retired shell names resolve to their capability-complete parent;
            // the second field is the canonical title after migration.
            ("Convos", "Inbox", "conversations"),
            ("Sessions", "Sessions", "sessions"),
            ("Voice", "Voice", "voice"),
            ("Fleet", "Fleet", "fleet"),
            ("Hives", "Network", "network"),
        ];

        for (title, canonical, expected) in cases {
            let mut a = App::new();
            let action = a.update(Event::TuiIntent {
                id: 1,
                intent: "set_tab".into(),
                args: serde_json::json!({"tab": title}),
            });
            let Action::IntentResultWithFollowup { follow_up, .. } = action else {
                panic!("expected follow-up for set_tab {title}");
            };

            match (expected, *follow_up) {
                ("conversations", Action::FetchConversations { state, kind }) => {
                    assert_eq!(state, "open");
                    assert_eq!(kind, "all");
                    assert!(a.conversations_loading);
                }
                ("sessions", Action::FetchSessionBrowser { query, .. }) => {
                    assert!(query.is_empty());
                    assert!(a.session_browser.loading);
                }
                ("voice", Action::VoiceChan(crate::voice_ui::VoiceCmd::Connect)) => {
                    assert!(!a.voice_ui.connected);
                }
                ("fleet", Action::FetchFleetAssignments) => {}
                ("network", Action::FetchNetworkBoard) => {}
                _ => panic!("unexpected follow-up for set_tab {title}"),
            }
            assert_eq!(a.tab.title(), canonical);
        }
    }

    // --- P-011 SU-session cutover (pui-su-session-runtime-correction-2026-08-27) ---
    //
    // The pure routing policy is covered in su_session.rs. These assert the two
    // things only `App` can answer: how an ABSENT flag resolves, and that the
    // composer's Enter key really applies the decision (including its telemetry)
    // rather than keeping an inline branch that drifted from it.

    /// Put the app in the state a real owner is in when they press Enter.
    fn composing(text: &str) -> App {
        let mut a = App::new();
        a.tab = Tab::Operator;
        a.chat_composing = true;
        a.chat_input = text.to_string();
        a
    }

    /// PUBLIC_RELEASE_UX.md "Below 80 columns or 20 rows": while the blocking
    /// too-small view shows, typed keys and pastes are held so the hidden draft
    /// is safe, and a resize back to the minimum resumes that same draft.
    #[test]
    fn too_small_holds_input_and_a_resize_back_resumes_the_draft() {
        let mut a = composing("kept draft");
        a.update(Event::Resize(79, 40));
        assert_eq!(
            a.on_key(KeyCode::Char('x'), KeyModifiers::NONE),
            Action::None
        );
        assert_eq!(a.on_key(KeyCode::Enter, KeyModifiers::NONE), Action::None);
        assert_eq!(a.update(Event::Paste("pasted".into())), Action::None);
        a.update(Event::Resize(120, 19));
        assert_eq!(
            a.on_key(KeyCode::Backspace, KeyModifiers::NONE),
            Action::None
        );
        assert_eq!(a.chat_input, "kept draft", "nothing hidden changed");
        assert!(a.chat_composing && !a.should_quit);

        a.update(Event::Resize(80, 20));
        a.on_key(KeyCode::Char('!'), KeyModifiers::NONE);
        assert!(a.chat_input.contains('!'), "typing reaches the draft again");
        assert!(a.chat_input.contains("kept draft"));
    }

    /// A pinned dock pane is sized by its layout, so it never blocks: a narrow
    /// colony pane keeps rendering and taking keys.
    #[test]
    fn a_pinned_dock_pane_is_never_too_small() {
        let mut a = App::new();
        a.update(Event::Resize(50, 12));
        assert!(a.too_small());
        a.pinned = Some(Tab::Operator);
        assert!(!a.too_small());
    }

    /// q and Ctrl-C still quit from the blocking view, as they do from navigation.
    #[test]
    fn too_small_still_quits_on_q_and_ctrl_c() {
        for (code, mods) in [
            (KeyCode::Char('q'), KeyModifiers::NONE),
            (KeyCode::Char('c'), KeyModifiers::CONTROL),
        ] {
            let mut a = composing("draft");
            a.update(Event::Resize(60, 16));
            assert_eq!(a.on_key(code, mods), Action::Quit);
            assert!(a.should_quit);
        }
    }

    #[test]
    fn enter_on_a_new_conversation_opens_an_su_session_by_default() {
        let mut a = composing("hello");
        let action = a.on_key(KeyCode::Enter, KeyModifiers::NONE);
        match action {
            Action::OpenSuSession {
                backend, launch, ..
            } => {
                assert_eq!(backend, crate::su_session::PUI_DEFAULT_SU_BACKEND);
                // WI-10004158 / D-011: an unchosen account is omitted; launch-su
                // resolves it (D-014, pinned by launch-su.test.ts 'an omitted OMP
                // account follows model'), so psu never waits on its picker.
                assert_eq!(
                    launch.account, None,
                    "an account the owner never chose must not be sent as an explicit choice"
                );
            }
            other => panic!("a new conversation must default to the SU host, got {other:?}"),
        }
        assert_eq!(
            a.su_last_dispatch.map(|d| d.reason),
            Some(crate::su_session::SuDispatchReason::CutoverDefault)
        );
    }

    #[test]
    fn su_first_draft_survives_until_its_own_acknowledgement() {
        let text = "  exact draft λ  ";
        let mut app = composing(text);
        let action = app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert!(
            matches!(action, Action::OpenSuSession { initial_turn: Some(ref s), .. } if s == text)
        );
        assert_eq!(app.chat_input, text);
        assert!(
            app.chat_messages.is_empty(),
            "unaccepted text is still a draft"
        );
        let pending = app.su_pending_turn.clone().unwrap();
        let identity: crate::su_session::SuSessionIdentity =
            serde_json::from_value(su_event_base("backend", 1)["session"].clone()).unwrap();
        // A reply for another command must never clear this draft.
        app.update(Event::SuTurnPrepared {
            command_id: pending.command_id.clone(),
            command: json!({"target":identity}),
        });
        app.update(Event::SuTurnAcknowledged {
            command_id: "foreign".into(),
            session: identity.clone(),
            replay_snapshot: None,
        });
        assert_eq!(app.chat_input, text);
        app.update(Event::SuTurnAcknowledged {
            command_id: pending.command_id.clone(),
            session: identity,
            replay_snapshot: None,
        });
        assert!(app.chat_input.is_empty());
        assert!(app.su_pending_turn.is_none());
        assert_eq!(app.chat_messages.len(), 1);
        assert_eq!(app.chat_messages[0].content, text);
    }

    #[test]
    fn selected_attachment_reference_reaches_the_accepted_turn_and_then_clears() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::write(tmp.path().join("context.md"), "project context").unwrap();
        let mut app = composing("  inspect this λ  ");
        app.project_root = tmp.path().to_path_buf();
        app.attachments.add(
            crate::file_picker::attach(tmp.path(), std::path::Path::new("context.md")).unwrap(),
        );

        let action = app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        let submitted = match action {
            Action::OpenSuSession {
                initial_turn: Some(text),
                ..
            } => text,
            other => panic!("attachment turn must open the SU session, got {other:?}"),
        };
        assert_eq!(submitted, "  inspect this λ  \n@context.md");
        let pending = app.su_pending_turn.clone().unwrap();
        assert_eq!(pending.draft, "  inspect this λ  ");
        assert_eq!(pending.attachment_references, vec!["@context.md"]);
        assert_eq!(app.chat_input, "  inspect this λ  ");
        assert_eq!(app.attachments.len(), 1);

        app.acknowledge_su_turn(&pending.command_id);

        assert!(app.chat_input.is_empty());
        assert!(app.attachments.is_empty());
        assert_eq!(
            app.chat_history.last().map(String::as_str),
            Some("  inspect this λ  ")
        );
        assert_eq!(
            app.chat_messages.last().map(|m| m.content.as_str()),
            Some(submitted.as_str())
        );
    }

    #[test]
    fn su_refusal_releases_busy_and_unknown_retry_keeps_the_command() {
        let mut app = composing("do it once");
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        let pending = app.su_pending_turn.clone().unwrap();
        let command = json!({"commandId":pending.command_id,"content":pending.content});
        app.update(Event::SuTurnPrepared {
            command_id: pending.command_id.clone(),
            command: command.clone(),
        });
        app.update(Event::SuTurnFailed {
            command_id: pending.command_id.clone(),
            message: "connection lost".into(),
            uncertain: true,
        });
        assert!(!app.chat_streaming);
        assert_eq!(app.chat_input, "do it once");
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert_eq!(
            app.su_pending_turn.as_ref().unwrap().command_id,
            pending.command_id
        );
        assert_eq!(
            app.su_pending_turn.as_ref().unwrap().command.as_ref(),
            Some(&command)
        );
        app.update(Event::SuTurnFailed {
            command_id: pending.command_id,
            message: "not accepted".into(),
            uncertain: false,
        });
        assert!(!app.chat_streaming);
        assert_eq!(app.chat_input, "do it once");
    }

    /// EI-24375699124551107 (P-027): an uncertain turn keeps its draft in the
    /// composer; the owner types the NEXT message after it and presses Enter.
    /// The reconcile must replay the ORIGINAL command, and the new text must be
    /// queued and sent afterwards as its own command, never swallowed.
    #[test]
    fn uncertain_reconcile_queues_the_next_message_instead_of_swallowing_it() {
        let mut app = composing("P13 long 37");
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        let pending = app.su_pending_turn.clone().unwrap();
        let command = json!({"commandId":pending.command_id,"content":pending.content});
        app.update(Event::SuTurnPrepared {
            command_id: pending.command_id.clone(),
            command: command.clone(),
        });
        app.update(Event::SuTurnFailed {
            command_id: pending.command_id.clone(),
            message: "Acceptance timed out".into(),
            uncertain: true,
        });
        assert_eq!(app.chat_input, "P13 long 37");

        // Attached sessions send the turn; this fixture opens one with it.
        fn turn_text(action: &Action) -> Option<&str> {
            match action {
                Action::SendSuSessionTurn(text) => Some(text),
                Action::OpenSuSession { initial_turn, .. } => initial_turn.as_deref(),
                _ => None,
            }
        }
        app.chat_input.push_str("P13 long 38");
        let action = app.on_key(KeyCode::Enter, KeyModifiers::NONE);

        assert_eq!(
            turn_text(&action),
            Some("P13 long 37"),
            "reconcile must replay the original turn, got {action:?}"
        );
        let reconciling = app.su_pending_turn.as_ref().unwrap();
        assert_eq!(reconciling.command_id, pending.command_id);
        assert_eq!(reconciling.command.as_ref(), Some(&command));
        assert_eq!(app.chat_queued, vec!["P13 long 38".to_string()]);
        assert_eq!(app.chat_input, "P13 long 37");

        app.acknowledge_su_turn(&pending.command_id);
        app.chat_streaming = false;
        app.su_open_in_flight = false;
        let next = app.drain_queued_turn();
        assert_eq!(
            next.as_ref().and_then(turn_text),
            Some("P13 long 38"),
            "the queued message must send as its own turn, got {next:?}"
        );
        let sent = app.su_pending_turn.as_ref().unwrap();
        assert_ne!(sent.command_id, pending.command_id);
        assert_eq!(sent.content, "P13 long 38");
        assert!(app.chat_queued.is_empty());
    }

    /// A slow acknowledgement keeps the in-flight draft visible; typing the
    /// next message after it and pressing Enter queues ONLY the new text, so
    /// the queued turn never re-sends the in-flight one inside itself.
    #[test]
    fn queue_during_slow_ack_takes_only_the_text_after_the_retained_draft() {
        let mut app = composing("first");
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert!(app.chat_streaming);
        assert_eq!(app.chat_input, "first");
        app.chat_input.push_str(" second");
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert_eq!(app.chat_queued, vec![" second".to_string()]);

        // An edited retained draft is a new message as a whole.
        let mut edited = composing("first");
        edited.on_key(KeyCode::Enter, KeyModifiers::NONE);
        edited.chat_input = "fixed first".into();
        edited.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert_eq!(edited.chat_queued, vec!["fixed first".to_string()]);
    }

    #[test]
    fn su_startup_failure_keeps_draft_and_ack_does_not_erase_new_edits() {
        let mut app = composing("first");
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        let id = app.su_pending_turn.as_ref().unwrap().command_id.clone();
        app.update(Event::SuSessionError("engine unavailable".into()));
        assert_eq!(app.chat_input, "first");
        assert!(!app.chat_streaming);
        app.chat_input = "next draft".into();
        app.acknowledge_su_turn(&id);
        assert_eq!(app.chat_input, "next draft");
    }

    /// Drive a fresh pane to "a turn is running and acknowledged" — the state an
    /// owner is actually in when they start typing the next thing.
    fn running_turn(first: &str) -> App {
        let mut app = composing(first);
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        let id = app.su_pending_turn.as_ref().unwrap().command_id.clone();
        app.acknowledge_su_turn(&id);
        assert!(app.chat_streaming, "the first turn is in flight");
        assert!(
            app.su_pending_turn.is_none(),
            "and acknowledged, so the queue is free to advance"
        );
        app
    }

    fn dispatched_text(action: &Action) -> Option<&str> {
        match action {
            Action::SendSuSessionTurn(t) => Some(t.as_str()),
            Action::OpenSuSession {
                initial_turn: Some(t),
                ..
            } => Some(t.as_str()),
            _ => None,
        }
    }

    #[test]
    fn enter_during_a_turn_queues_the_line_instead_of_swallowing_the_key() {
        let mut app = running_turn("first");
        app.chat_input = "second".into();
        let action = app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert_eq!(action, Action::Render);
        assert_eq!(app.chat_queued, vec!["second".to_string()]);
        assert!(
            app.chat_input.is_empty(),
            "the line moved to the queue, so leaving it in the composer would \
             show it twice and invite a double send"
        );
        assert!(
            app.su_pending_turn.is_none(),
            "queuing must not dispatch — the running turn owns the session"
        );
        let note = app.session_note.clone().unwrap_or_default();
        assert!(note.contains("Queued"), "{note}");
    }

    #[test]
    fn a_queued_line_sends_itself_once_the_turn_settles() {
        let mut app = running_turn("first");
        app.chat_input = "second".into();
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);

        app.finish_chat_turn();
        let action = app.update(Event::Tick);
        assert_eq!(
            dispatched_text(&action),
            Some("second"),
            "the tick must dispatch the queued line, got {action:?}"
        );
        assert!(app.chat_queued.is_empty(), "and consume it exactly once");
        assert!(app.chat_streaming, "the queued turn is now the running one");
    }

    /// CALIBRATION for `a_queued_line_sends_itself_once_the_turn_settles`: that
    /// test passes for a drain hard-wired to fire on every tick. This is the
    /// assertion that fails for one.
    #[test]
    fn the_queue_does_not_drain_while_the_turn_is_still_running() {
        let mut app = running_turn("first");
        app.chat_input = "second".into();
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);

        for _ in 0..5 {
            let action = app.update(Event::Tick);
            assert_eq!(
                dispatched_text(&action),
                None,
                "a queued line must not be sent into a turn that is still running"
            );
        }
        assert_eq!(app.chat_queued, vec!["second".to_string()]);
    }

    /// CALIBRATION for the second drain guard. An unacknowledged turn may still
    /// be in flight on the wire, so draining onto it mints the duplicate turn
    /// that `dispatch_chat_turn`'s reconcile branch exists to prevent — and
    /// `chat_streaming` alone does NOT catch it: a delivery failure clears
    /// streaming while leaving the turn outstanding.
    #[test]
    fn the_queue_does_not_drain_onto_an_unacknowledged_turn() {
        let mut app = running_turn("first");
        app.chat_input = "second".into();
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);

        // The exact state a failed-but-uncertain delivery leaves behind.
        app.su_pending_turn = Some(PendingSuTurn {
            command_id: "pui-outstanding".into(),
            content: "first".into(),
            draft: "first".into(),
            attachment_references: Vec::new(),
            command: None,
            uncertain: true,
            error: Some("connection lost".into()),
        });
        app.chat_streaming = false;

        let action = app.update(Event::Tick);
        assert_eq!(
            dispatched_text(&action),
            None,
            "an outstanding turn blocks the queue even though nothing is streaming"
        );
        assert_eq!(app.chat_queued, vec!["second".to_string()]);
    }

    #[test]
    fn queued_lines_send_in_the_order_they_were_composed() {
        let mut app = running_turn("first");
        for text in ["second", "third"] {
            app.chat_input = text.into();
            app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        }
        assert_eq!(app.chat_queued, vec!["second".to_string(), "third".into()]);

        app.finish_chat_turn();
        let action = app.update(Event::Tick);
        assert_eq!(dispatched_text(&action), Some("second"));

        // "third" must wait for "second" to settle, not ride the same tick.
        let action = app.update(Event::Tick);
        assert_eq!(dispatched_text(&action), None);

        let id = app.su_pending_turn.as_ref().unwrap().command_id.clone();
        app.acknowledge_su_turn(&id);
        app.finish_chat_turn();
        let action = app.update(Event::Tick);
        assert_eq!(dispatched_text(&action), Some("third"));
        assert!(app.chat_queued.is_empty());
    }

    /// A queued line must be byte-identical to the same text sent with Enter —
    /// `su_first_draft_survives_until_its_own_acknowledgement` pins that exact
    /// whitespace for the interactive path, and a queue that trimmed would make
    /// the two paths disagree about what the owner actually sent.
    #[test]
    fn a_queued_line_is_sent_exactly_as_composed() {
        let text = "  exact queued λ  ";
        let mut app = running_turn("first");
        app.chat_input = text.into();
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert_eq!(app.chat_queued, vec![text.to_string()]);

        app.finish_chat_turn();
        let action = app.update(Event::Tick);
        assert_eq!(dispatched_text(&action), Some(text));
        assert_eq!(app.su_pending_turn.as_ref().unwrap().content, text);
    }

    #[test]
    fn an_owner_interrupt_clears_the_queue() {
        let mut app = running_turn("first");
        app.chat_input = "second".into();
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert!(!app.chat_queued.is_empty());

        app.on_key(KeyCode::Char('x'), KeyModifiers::CONTROL);
        assert!(
            app.chat_queued.is_empty(),
            "Ctrl+X means stop; the drain fires within one tick, so a queue that \
             survived the interrupt would immediately restart the halted work"
        );

        // And it stays cleared once the cancelled turn settles.
        app.finish_chat_turn();
        let action = app.update(Event::Tick);
        assert_eq!(dispatched_text(&action), None);
    }

    #[test]
    fn rebinding_the_conversation_clears_the_queue() {
        let mut app = running_turn("first");
        app.chat_input = "second".into();
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);

        app.reset_agent_chat_binding();
        assert!(
            app.chat_queued.is_empty(),
            "a line composed for THIS conversation must never be delivered to \
             whatever is bound next"
        );
        let action = app.update(Event::Tick);
        assert_eq!(dispatched_text(&action), None);
    }

    /// Make the bound conversation refuse writes, the same way the pre-cutover
    /// fixture does — a legacy class is the one state where a composed line can
    /// be accepted into the queue and then turn out to be undeliverable.
    fn make_read_only(app: &mut App) {
        app.agent_chat_id = Some("chat-legacy".into());
        app.pui_runtime_class = Some(crate::su_session::PuiRuntimeClass::LegacyOwnedLoop);
    }

    fn undelivered_lines(app: &App) -> Vec<&str> {
        app.chat_messages
            .iter()
            .filter(|m| m.role == "undelivered")
            .map(|m| m.content.as_str())
            .collect()
    }

    /// The plan's product-flow contract is that no state "accepts a message
    /// that will simply disappear". A queued line whose conversation turns out
    /// to refuse writes is precisely that state, and the composer holds only
    /// ONE line — so everything past the first needs a home, not a count.
    #[test]
    fn a_refused_queue_returns_the_head_and_keeps_every_other_line() {
        let mut app = running_turn("first");
        for line in ["second", "third", "fourth"] {
            app.chat_input = line.into();
            app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        }
        assert_eq!(app.chat_queued.len(), 3, "fixture: three lines queued");
        make_read_only(&mut app);

        app.finish_chat_turn();
        app.update(Event::Tick);

        assert_eq!(
            app.chat_input, "second",
            "the head goes back to the composer, which was free"
        );
        assert_eq!(
            undelivered_lines(&app),
            ["third", "fourth"],
            "and the tail is PRESERVED in the transcript — it used to be \
             discarded with nothing but a count to show for it"
        );
        assert!(
            app.chat_queued.is_empty(),
            "the queue still stops: a refusal is a property of the conversation, \
             so retrying every tick would spin forever"
        );
    }

    /// The worse half of the same defect: when the composer was OCCUPIED the
    /// head was dropped outright, and the note still read "The first is back in
    /// the composer" — a lost message reported as a recovered one. A truthful
    /// "discarded" would at least have told the owner to retype.
    #[test]
    fn a_refused_queue_never_overwrites_a_draft_nor_lies_about_where_it_went() {
        let mut app = running_turn("first");
        app.chat_input = "second".into();
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        // The owner started composing again while the turn was still running.
        app.chat_input = "a draft I am still editing".into();
        make_read_only(&mut app);

        app.finish_chat_turn();
        app.update(Event::Tick);

        assert_eq!(
            app.chat_input, "a draft I am still editing",
            "a live draft is never overwritten by a stranded line"
        );
        assert_eq!(
            undelivered_lines(&app),
            ["second"],
            "and the stranded line survives instead of vanishing"
        );
        let note = app.session_note.as_deref().unwrap_or_default();
        assert!(
            note.contains("kept in the transcript"),
            "the note must say where the line actually went: {note}"
        );
        assert!(
            !note.contains("back in the composer"),
            "and must NOT claim a recovery that did not happen: {note}"
        );
    }

    /// Calibration for the two tests above. They assert over a queue that was
    /// REFUSED; if the fixture ever stopped refusing, the queue would simply
    /// drain and both would keep passing while measuring nothing. This is the
    /// same fixture MINUS the read-only class, and it must behave oppositely.
    #[test]
    fn the_stranded_queue_tests_are_measuring_a_real_refusal() {
        let mut app = running_turn("first");
        app.chat_input = "second".into();
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);

        app.finish_chat_turn();
        let action = app.update(Event::Tick);

        assert_eq!(
            dispatched_text(&action),
            Some("second"),
            "without the read-only class the queue DRAINS"
        );
        assert!(
            undelivered_lines(&app).is_empty(),
            "and a delivered line is never marked undelivered"
        );
    }

    /// An unsent line must not vanish just because the conversation was
    /// unbound. It is not re-aimed at whatever binds next — that would deliver
    /// the owner's message to a different agent — but the composer is their own
    /// scratch buffer and survives the switch, so it is recoverable there.
    #[test]
    fn rebinding_recovers_the_unsent_line_into_a_free_composer() {
        let mut app = running_turn("first");
        app.chat_input = "second".into();
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert!(
            app.chat_input.is_empty(),
            "fixture: queuing frees the composer"
        );

        app.reset_agent_chat_binding();

        assert_eq!(app.chat_input, "second", "recoverable, and still unsent");
        let action = app.update(Event::Tick);
        assert_eq!(
            dispatched_text(&action),
            None,
            "recovering it must not also SEND it at the new binding"
        );
    }

    /// Preserving an unsent line in the transcript must not smuggle it into the
    /// MODEL's context. The transcript is a local record the owner can read and
    /// copy; `chat_history_for_send` is the converse `messages` array. Never
    /// delivered has to mean never delivered — and the positive control is what
    /// keeps this from passing by filtering everything.
    #[test]
    fn an_undelivered_line_is_never_sent_to_the_model_as_history() {
        let mut app = App::new();
        app.chat_messages.push(ChatMessage::user("a real turn"));
        app.chat_messages
            .push(ChatMessage::assistant("a real reply"));
        app.chat_messages
            .push(ChatMessage::undelivered("never left the composer"));

        let sent = app.chat_history_for_send();

        assert_eq!(
            sent,
            vec![
                ("user".to_string(), "a real turn".to_string()),
                ("assistant".to_string(), "a real reply".to_string()),
            ],
            "committed turns still go (the positive control), the unsent line \
             does not"
        );
    }

    #[test]
    fn enter_on_an_empty_composer_during_a_turn_queues_nothing() {
        let mut app = running_turn("first");
        app.chat_input = "   ".into();
        let action = app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert_eq!(action, Action::Render);
        assert!(app.chat_queued.is_empty());
    }

    #[test]
    fn su_replayed_receipt_restores_the_actual_running_or_idle_state() {
        for running in [false, true] {
            let mut app = composing("one saved turn");
            app.on_key(KeyCode::Enter, KeyModifiers::NONE);
            app.set_su_session_binding(su_binding());
            app.agent_chat_id = Some("chat-1".into());
            let mut snapshot = su_archived_snapshot(1, 20, None);
            snapshot.terminal = false;
            snapshot.descriptor.lifecycle = if running {
                crate::su_session::SuSessionLifecycleState::Running
            } else {
                crate::su_session::SuSessionLifecycleState::Ready
            };
            let identity = snapshot.descriptor.identity.clone();
            let id = app.su_pending_turn.as_ref().unwrap().command_id.clone();
            app.update(Event::SuTurnPrepared {
                command_id: id.clone(),
                command: json!({"target": identity}),
            });
            app.update(Event::SuTurnFailed {
                command_id: id.clone(),
                message: "lost receipt".into(),
                uncertain: true,
            });
            app.chat_streaming = true; // Owner retries the exact pending command.
            app.update(Event::SuTurnAcknowledged {
                command_id: id,
                session: identity,
                replay_snapshot: Some(Box::new(snapshot)),
            });
            assert!(app.chat_input.is_empty());
            assert!(app.su_pending_turn.is_none());
            assert_eq!(app.chat_streaming, running);
            assert_eq!(
                app.chat_messages
                    .iter()
                    .filter(|m| m.role == "user")
                    .count(),
                1
            );
        }
    }

    #[test]
    fn su_receipt_and_native_echo_render_one_owner_turn_and_one_final_reply() {
        for ack_first in [false, true] {
            let mut app = composing("one draft");
            app.on_key(KeyCode::Enter, KeyModifiers::NONE);
            app.set_su_session_binding(su_binding());
            app.agent_chat_id = Some("chat-1".into());
            let id = app.su_pending_turn.as_ref().unwrap().command_id.clone();
            let turn_id = format!("pui-turn-{id}");
            if ack_first {
                app.acknowledge_su_turn(&id);
            }
            let mut owner = su_event_base("transcript", 1);
            owner["phase"] = json!("completed");
            owner["turnId"] = json!(turn_id);
            owner["role"] = json!("owner");
            owner["channel"] = json!("text");
            owner["content"] = json!("one draft");
            app.apply_su_session_event(su_event(owner));
            if !ack_first {
                app.acknowledge_su_turn(&id);
            }
            let mut receipt = su_event_base("command_result", 2);
            receipt["commandId"] = json!(id);
            receipt["commandType"] = json!("owner_turn");
            receipt["status"] = json!("completed");
            app.apply_su_session_event(su_event(receipt));
            assert!(
                app.chat_streaming,
                "delivery receipt is not turn completion"
            );
            for (offset, phase) in ["started", "delta", "completed"].into_iter().enumerate() {
                let mut reply = su_event_base("transcript", offset as u64 + 3);
                reply["phase"] = json!(phase);
                reply["turnId"] = json!(turn_id);
                reply["role"] = json!("assistant");
                reply["channel"] = json!("text");
                if phase != "started" {
                    reply["content"] = json!("one response");
                }
                app.apply_su_session_event(su_event(reply));
            }
            assert_eq!(app.chat_messages.len(), 2);
            assert_eq!(app.chat_messages[0].content, "one draft");
            assert_eq!(app.chat_messages[1].content, "one response");
            assert!(!app.chat_messages[1].streaming);
            assert!(app.chat_streaming, "a completed segment can precede a tool");
            let mut completed = su_event_base("lifecycle", 6);
            completed["state"] = json!("waiting-for-owner");
            completed["runtimeGeneration"] = json!(0);
            app.apply_su_session_event(su_event(completed));
            assert!(!app.chat_streaming);
        }
    }

    #[test]
    fn su_resume_ready_unlocks_after_historical_assistant_replay() {
        let mut app = composing("");
        app.set_su_session_binding(su_binding());
        app.agent_chat_id = Some("chat-1".into());
        let mut running = su_event_base("lifecycle", 1);
        running["state"] = json!("running");
        running["runtimeGeneration"] = json!(1);
        app.apply_su_session_event(su_event(running));
        for (offset, phase) in ["started", "delta", "completed"].into_iter().enumerate() {
            let mut reply = su_event_base("transcript", offset as u64 + 2);
            reply["phase"] = json!(phase);
            reply["turnId"] = json!("historical-turn");
            reply["role"] = json!("assistant");
            reply["channel"] = json!("text");
            if phase != "started" {
                reply["content"] = json!("restored reply");
            }
            app.apply_su_session_event(su_event(reply));
        }
        assert!(
            app.chat_streaming,
            "replay has not reached current readiness"
        );
        let mut ready = su_event_base("lifecycle", 5);
        ready["state"] = json!("ready");
        ready["runtimeGeneration"] = json!(1);
        app.apply_su_session_event(su_event(ready));
        assert!(!app.chat_streaming);
        assert_eq!(app.chat_messages.last().unwrap().content, "restored reply");
        app.chat_input = "continue this session".into();
        assert_eq!(
            app.on_key(KeyCode::Enter, KeyModifiers::NONE),
            Action::SendSuSessionTurn("continue this session".into())
        );
    }

    #[test]
    fn fresh_su_session_carries_projected_mode_and_explicit_launch_context() {
        let mut a = composing("start the selected plan");
        a.set_operator_config(crate::models::OperatorConfig {
            agent: Some(crate::models::AgentConfigResponse {
                launchable_modes: vec![crate::session_config::LaunchableMode {
                    id: "auto".into(),
                    title: "AUTO".into(),
                    one_liner: "Act without confirmation stops.".into(),
                }],
                ..Default::default()
            }),
            ..Default::default()
        });
        a.open_mode_picker();
        assert_eq!(
            a.session_picker.as_ref().unwrap().options[1].id,
            "auto",
            "the picker must use the server-projected registry row"
        );
        a.session_picker.as_mut().unwrap().sel = 1;
        assert_eq!(a.commit_session_picker(), Action::Render);

        a.chat_model = Some("gpt-5.6-sol".into());
        a.chat_effort = Some("high".into());
        a.su_launch_fleet = Some("fed-drill".into());
        a.su_launch_seat = Some("sonnet:high:auto".into());
        a.open_account_picker();
        assert_eq!(
            a.session_picker.as_ref().unwrap().options[1].id,
            crate::session_config::ACCOUNT_DEFAULT
        );
        assert!(
            !a.session_picker.as_ref().unwrap().options[1].disabled,
            "fresh launch must make the default system account selectable"
        );
        a.session_picker.as_mut().unwrap().sel = 1;
        assert_eq!(a.commit_session_picker(), Action::Render);
        a.plan_filter.insert("plan-a".into());

        match a.on_key(KeyCode::Enter, KeyModifiers::NONE) {
            Action::OpenSuSession {
                harness,
                launch,
                initial_turn,
                ..
            } => {
                assert_eq!(harness, "papercup");
                assert_eq!(launch.plan_slug.as_deref(), Some("plan-a"));
                assert_eq!(launch.fleet.as_deref(), Some("fed-drill"));
                assert_eq!(launch.seat.as_deref(), Some("sonnet:high:auto"));
                assert_eq!(launch.model.as_deref(), Some("gpt-5.6-sol"));
                assert_eq!(launch.effort.as_deref(), Some("high"));
                assert_eq!(launch.account.as_deref(), Some("default"));
                assert_eq!(launch.mode.as_deref(), Some("auto"));
                assert_eq!(initial_turn.as_deref(), Some("start the selected plan"));
            }
            other => panic!("expected typed SU-session launch options, got {other:?}"),
        }

        let mut ambiguous = composing("do not guess a plan");
        ambiguous.plan_filter.insert("plan-a".into());
        ambiguous.plan_filter.insert("plan-b".into());
        assert_eq!(
            ambiguous.su_session_launch_options().plan_slug,
            None,
            "a multi-plan list filter is not launch authority"
        );
    }

