    /// The window this closes: the picker commits `session:<id>`, and the load is
    /// still in flight. Before P-011 a cleared `su_backend` was enough to keep a
    /// turn typed here off the SU host; now that the SU host is the DEFAULT, the
    /// selection has to be held as explicitly unclassified or that same keystroke
    /// opens a new SU session on an old chat.
    #[test]
    fn selecting_a_chat_holds_it_unclassified_until_its_class_arrives() {
        let mut a = App::new();
        a.agent_chat_summaries = vec![chat_summary_for("chat-x")];
        let action = select_session_option(&mut a, "chat:chat-x");
        assert!(matches!(action, Action::LoadAgentChat { .. }), "{action:?}");
        assert_eq!(
            a.pui_runtime_class,
            Some(crate::su_session::PuiRuntimeClass::Unclassified)
        );

        let mut b = a;
        b.tab = Tab::Operator;
        b.chat_composing = true;
        b.chat_input = "typed while the load was in flight".into();
        let action = b.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert_eq!(action, Action::Render);
        assert_eq!(b.chat_input, "typed while the load was in flight");
        assert!(!b.chat_streaming);
        assert!(b
            .session_note
            .as_deref()
            .unwrap()
            .contains("read-only history"));
    }

    /// P-013 recurrence guard: the PUI must not grow a second owner-loop turn
    /// seam after the typed SU-session host cutover. This scans the actual
    /// dispatch/stream sources and pairs every negative assertion with a
    /// positive control on the surviving SU-session adapter, so a moved or
    /// unread source cannot make the guard pass vacuously.
    #[test]
    fn pui_runtime_divorce_does_not_reintroduce_owned_loop_dispatch() {
        let app_src = include_str!("app.rs");
        let main_src = include_str!("main.rs");
        let retired = [
            ["Action", "SendChat"].join("::"),
            ["SuDispatchTarget", "OwnedLoop"].join("::"),
            ["PUI", "SU_SESSION_HOST"].join("_"),
            ["stream", "agent_chat_turn"].join("_"),
            ["start", "agent_chat_turn"].join("_"),
        ];
        for symbol in retired {
            assert!(
                !app_src.contains(&symbol) && !main_src.contains(&symbol),
                "retired PUI owned-loop symbol returned: {symbol}"
            );
        }

        // Positive controls: these are the canonical seams that must remain
        // reachable after the divorce. If either source moved or the include
        // path is wrong, the negative checks above would otherwise be vacuous.
        let read_only = ["SuDispatchTarget", "ReadOnly"].join("::");
        assert!(app_src.contains(&read_only), "dispatch source not measured");
        assert!(
            main_src.contains("stream_su_session_events"),
            "SU-session stream adapter not measured"
        );
    }

    // --- P10 Settings tab (feature flags) ---

    fn flags(pairs: &[(&str, bool)]) -> FlagsResponse {
        let mut m = std::collections::BTreeMap::new();
        for (k, v) in pairs {
            m.insert((*k).to_string(), *v);
        }
        FlagsResponse {
            flags: m,
            source: "test-src".into(),
        }
    }

    #[test]
    fn set_flags_sorts_by_key_and_keeps_source() {
        let mut a = App::new();
        a.set_flags(flags(&[("z-flag", true), ("a-flag", false)]));
        assert_eq!(a.flags.len(), 2);
        assert_eq!(a.flags[0], ("a-flag".to_string(), false));
        assert_eq!(a.flags[1], ("z-flag".to_string(), true));
        assert_eq!(a.flags_source, "test-src");
    }

    #[test]
    fn retired_settings_title_aliases_to_config() {
        let mut a = App::new();
        // `0` was the retired Settings shell shortcut; it must not become a
        // second public route.  Persisted/intention-based restores still map
        // the old title to the capability-complete Config destination.
        assert_eq!(
            a.on_key(KeyCode::Char('0'), KeyModifiers::empty()),
            Action::None
        );
        assert_eq!(Tab::from_switch_key('0'), None);
        assert_eq!(Tab::from_title("Settings"), Some(Tab::Config));
        let result = a
            .apply_intent("set_tab", &json!({"tab": "Settings"}))
            .unwrap();
        assert_eq!(result, json!({"ok": true, "tab": "Config"}));
        assert_eq!(a.tab, Tab::Config);
    }

