    // --- P12b palette save/restore + launch-tracking ---

    #[test]
    fn parse_palette_commands() {
        assert_eq!(
            parse_palette_command("layouts"),
            Some(PaletteCommand::ListLayouts)
        );
        assert_eq!(
            parse_palette_command(":crews"),
            Some(PaletteCommand::ListCrews)
        );
        assert_eq!(
            parse_palette_command("save-crew morning"),
            Some(PaletteCommand::SaveCrew("morning".into()))
        );
        assert_eq!(
            parse_palette_command(" save-layout  main "),
            Some(PaletteCommand::SaveLayout("main".into()))
        );
        assert_eq!(
            parse_palette_command("restore-crew x"),
            Some(PaletteCommand::RestoreCrew("x".into()))
        );
        assert_eq!(
            parse_palette_command("restore-layout y"),
            Some(PaletteCommand::RestoreLayout("y".into()))
        );
        // `:pickup <item>` resolves plan later (selected plan); `:pickup <plan> <item>` is explicit.
        assert_eq!(
            parse_palette_command(":pickup P-012"),
            Some(PaletteCommand::PickupPlanItem {
                harness: None,
                plan: None,
                item: "P-012".into()
            })
        );
        assert_eq!(
            parse_palette_command("pickup demo-plan P-012"),
            Some(PaletteCommand::PickupPlanItem {
                harness: None,
                plan: Some("demo-plan".into()),
                item: "P-012".into(),
            })
        );
        // `:release` mirrors `:pickup` (the P-005b inverse): bare item resolves
        // the plan later (selected plan); `<plan> <item>` is explicit.
        assert_eq!(
            parse_palette_command(":release P-012"),
            Some(PaletteCommand::ReleasePlanItem {
                harness: None,
                plan: None,
                item: "P-012".into()
            })
        );
        assert_eq!(
            parse_palette_command("release demo-plan P-012"),
            Some(PaletteCommand::ReleasePlanItem {
                harness: None,
                plan: Some("demo-plan".into()),
                item: "P-012".into(),
            })
        );
        // Missing arg / unknown / empty → None.
        assert_eq!(parse_palette_command("save-crew"), None);
        assert_eq!(parse_palette_command("pickup"), None);
        assert_eq!(parse_palette_command("release"), None);
        assert_eq!(parse_palette_command("bogus"), None);
        assert_eq!(parse_palette_command(""), None);
    }

    fn palette_hit(name: &str, schema: &str) -> ToolPaletteHit {
        ToolPaletteHit {
            name: name.into(),
            description: format!("{name} description"),
            arg_schema: schema.into(),
            returns: None,
            via: Some("both".into()),
        }
    }

    #[test]
    fn parses_tool_palette_command_and_required_schema_fields() {
        assert_eq!(
            parse_palette_command(":tool coordination locks"),
            Some(PaletteCommand::FindTool {
                query: "coordination locks".into(),
                harness: None,
                plan: None,
            })
        );
        assert_eq!(parse_palette_command(":tool"), None);

        let fields = required_tool_args(
            "alias-group:itemIds|item; query:string(1-500); limit?:integer(1-20); target:object{name:string}; one-of:items",
        );
        assert_eq!(
            fields,
            vec![
                ToolArgField {
                    name: "query".into(),
                    schema: "string(1-500)".into(),
                },
                ToolArgField {
                    name: "target".into(),
                    schema: "object{name:string}".into(),
                },
            ]
        );
        assert_eq!(
            parse_required_tool_arg(&fields[0], "locks").unwrap(),
            json!("locks")
        );
        assert!(parse_required_tool_arg(&fields[1], "not-json").is_err());
        assert_eq!(
            parse_optional_tool_args(r#"{"limit":3}"#).unwrap()["limit"],
            json!(3)
        );
        assert!(parse_optional_tool_args("[]").is_err());
    }

    #[test]
    fn install_lifecycle_palette_commands_parse() {
        use crate::self_install::LifecycleOp as L;
        let lifecycle = |op| Some(PaletteCommand::Lifecycle(op));
        assert_eq!(parse_palette_command(":about"), lifecycle(L::About));
        assert_eq!(parse_palette_command(":update"), lifecycle(L::CheckUpdates));
        assert_eq!(parse_palette_command("updates"), lifecycle(L::CheckUpdates));
        assert_eq!(
            parse_palette_command(":update /tmp/pui-0.2.0-linux-x86_64.tar.gz"),
            lifecycle(L::Update {
                from: "/tmp/pui-0.2.0-linux-x86_64.tar.gz".into(),
                sha256: None,
            })
        );
        assert_eq!(parse_palette_command(":rollback"), lifecycle(L::Rollback));
        assert_eq!(
            parse_palette_command(":uninstall"),
            lifecycle(L::Uninstall { purge: false })
        );
        assert_eq!(
            parse_palette_command(":uninstall purge"),
            lifecycle(L::Uninstall { purge: true })
        );
        assert_eq!(
            parse_palette_command(":uninstall everything"),
            None,
            "an unknown uninstall argument is refused, never guessed"
        );
        assert_eq!(
            parse_palette_command(":diagnostics"),
            lifecycle(L::Diagnostics)
        );
    }

    #[test]
    fn install_lifecycle_changes_apply_only_on_y_after_a_preview() {
        use crate::self_install::{LifecycleOp as L, LifecycleView};
        let mut app = App::new();
        app.palette_open = true;
        app.palette_input = ":rollback".into();
        assert_eq!(
            app.on_key(KeyCode::Enter, KeyModifiers::NONE),
            Action::Lifecycle {
                op: L::Rollback,
                confirmed: false
            }
        );
        assert!(app.lifecycle.as_ref().is_some_and(|panel| panel.busy));
        assert_eq!(
            app.on_key(KeyCode::Char('y'), KeyModifiers::NONE),
            Action::None,
            "nothing reacts while the preview is being computed"
        );

        app.update(Event::Lifecycle(LifecycleView {
            title: "Roll back PUI".into(),
            lines: vec!["rollback: 0.2.0-b → 0.1.0-a".into()],
            armed: Some(L::Rollback),
        }));
        assert_eq!(
            app.on_key(KeyCode::Char('n'), KeyModifiers::NONE),
            Action::None
        );
        assert_eq!(
            app.on_key(KeyCode::Char('y'), KeyModifiers::NONE),
            Action::Lifecycle {
                op: L::Rollback,
                confirmed: true
            }
        );
        assert!(app
            .lifecycle
            .as_ref()
            .is_some_and(|panel| panel.busy && panel.view.armed.is_none()));

        app.update(Event::Lifecycle(LifecycleView {
            title: "Roll back PUI".into(),
            lines: vec!["✓ rolled back to 0.1.0-a".into()],
            armed: None,
        }));
        assert_eq!(
            app.on_key(KeyCode::Char('y'), KeyModifiers::NONE),
            Action::None,
            "a result has nothing armed"
        );
        assert_eq!(app.on_key(KeyCode::Esc, KeyModifiers::NONE), Action::Render);
        assert!(app.lifecycle.is_none());
    }

    #[test]
    fn closing_an_armed_lifecycle_preview_applies_nothing() {
        use crate::self_install::{LifecycleOp as L, LifecycleView};
        for close in [KeyCode::Esc, KeyCode::Enter, KeyCode::Char('q')] {
            let mut app = App::new();
            app.update(Event::Lifecycle(LifecycleView {
                title: "Uninstall PUI".into(),
                lines: vec!["remove releases: …".into()],
                armed: Some(L::Uninstall { purge: true }),
            }));
            assert_eq!(
                app.on_key(close, KeyModifiers::NONE),
                Action::Render,
                "{close:?}"
            );
            assert!(app.lifecycle.is_none(), "{close:?}");
        }
    }

    #[test]
    fn tool_palette_search_arguments_invoke_and_result_are_one_guarded_flow() {
        let mut app = App::new();
        app.palette_open = true;
        app.palette_input = ":tool work item detail".into();
        let search = app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert_eq!(
            search,
            Action::Workbench(PaletteCommand::FindTool {
                query: "work item detail".into(),
                harness: None,
                plan: None,
            })
        );
        assert!(app.palette_open);
        assert!(matches!(
            app.tool_palette.as_ref().map(|state| &state.phase),
            Some(ToolPalettePhase::Searching)
        ));
        assert_eq!(app.palette_history, vec![":tool work item detail"]);

        // A stale result cannot repaint the current query.
        assert_eq!(
            app.update(Event::ToolPaletteSearchFinished {
                query: "older query".into(),
                tools: Ok(vec![palette_hit("wrong:tool", "")]),
                recipes: Ok(vec![]),
            }),
            Action::None
        );

        app.update(Event::ToolPaletteSearchFinished {
            query: "work item detail".into(),
            tools: Ok(vec![
                palette_hit("tools:find", "query:string(1-500)"),
                palette_hit("work_items:get", "id:string(1-120); detail?:boolean"),
            ]),
            recipes: Ok(vec![ToolPaletteRecipe {
                id: "recipe-work-item-detail".into(),
                title: "Work-item detail".into(),
                description: "read a work item".into(),
            }]),
        });
        assert!(matches!(
            app.tool_palette.as_ref().map(|state| &state.phase),
            Some(ToolPalettePhase::Results)
        ));
        app.on_key(KeyCode::Down, KeyModifiers::NONE);
        app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert!(matches!(
            app.tool_palette.as_ref().map(|state| &state.phase),
            Some(ToolPalettePhase::Arguments { index: 0, .. })
        ));

        app.palette_input = "WI-7".into();
        assert_eq!(
            app.on_key(KeyCode::Enter, KeyModifiers::NONE),
            Action::Render
        );
        app.palette_input = r#"{"detail":true}"#.into();
        let args = json!({"id":"WI-7","detail":true});
        assert_eq!(
            app.on_key(KeyCode::Enter, KeyModifiers::NONE),
            Action::Workbench(PaletteCommand::InvokeTool {
                query: "work item detail".into(),
                tool: palette_hit("work_items:get", "id:string(1-120); detail?:boolean"),
                args: args.clone(),
            })
        );
        assert!(matches!(
            app.tool_palette.as_ref().map(|state| &state.phase),
            Some(ToolPalettePhase::Running { .. })
        ));

        app.update(Event::ToolPaletteInvocationFinished {
            query: "work item detail".into(),
            tool: palette_hit("work_items:get", "id:string(1-120); detail?:boolean"),
            args,
            result: Ok(json!({"status":"open","id":"WI-7"})),
        });
        assert!(matches!(
            app.tool_palette.as_ref().map(|state| &state.phase),
            Some(ToolPalettePhase::Result {
                succeeded: true,
                ..
            })
        ));
    }

    #[test]
    fn palette_history_recalls_recent_commands_and_restores_the_draft() {
        let mut app = App::new();
        for command in ["layouts", "crews"] {
            app.palette_open = true;
            app.palette_input = command.into();
            let _ = app.on_key(KeyCode::Enter, KeyModifiers::NONE);
        }
        app.palette_open = true;
        app.palette_input = "draft".into();
        app.on_key(KeyCode::Up, KeyModifiers::NONE);
        assert_eq!(app.palette_input, "crews");
        app.on_key(KeyCode::Up, KeyModifiers::NONE);
        assert_eq!(app.palette_input, "layouts");
        app.on_key(KeyCode::Down, KeyModifiers::NONE);
        assert_eq!(app.palette_input, "crews");
        app.on_key(KeyCode::Down, KeyModifiers::NONE);
        assert_eq!(app.palette_input, "draft");
    }

