    #[test]
    fn compose_mode_captures_input_and_sends() {
        let mut a = App::new(); // starts on Operator
                                // Outside compose, digit keys still switch tabs.
        a.update(key('2', KeyModifiers::NONE));
        assert_eq!(a.tab, Tab::Inbox);
        a.update(key('1', KeyModifiers::NONE)); // back to Operator (leads the strip)
                                                // `i` focuses the composer; now keys are captured as text.
        a.update(key('i', KeyModifiers::NONE));
        assert!(a.chat_composing);
        a.update(key('h', KeyModifiers::NONE));
        a.update(key('2', KeyModifiers::NONE)); // a digit types, does NOT switch tab
        assert_eq!(a.chat_input, "h2");
        assert_eq!(a.tab, Tab::Operator);
        // Enter retains the draft until its correlated host acknowledgement.
        // Since P-011 an UNBOUND conversation's
        // first turn opens an SU session rather than an untyped provider path;
        // what this test is about is that the composed text is what gets sent.
        match a.update(ev(KeyCode::Enter)) {
            Action::OpenSuSession { initial_turn, .. } => {
                assert_eq!(initial_turn.as_deref(), Some("h2"));
            }
            other => panic!("expected the SU-session default, got {other:?}"),
        }
        assert_eq!(a.chat_input, "h2");
        assert!(a.chat_streaming);
        assert!(a.chat_messages.is_empty());
        let id = a.su_pending_turn.as_ref().unwrap().command_id.clone();
        a.acknowledge_su_turn(&id);
        assert!(a.chat_input.is_empty());
        assert_eq!(a.chat_messages.len(), 1);
        assert_eq!(a.chat_messages[0].role, "user");
        assert_eq!(a.chat_messages[0].content, "h2");
        // Enter while a turn is in flight is a no-op send.
        a.chat_input = "again".into();
        assert_eq!(a.update(ev(KeyCode::Enter)), Action::Render);
        assert_eq!(a.chat_messages.len(), 1);
    }

    #[test]
    fn compose_esc_leaves_and_ctrl_c_quits() {
        let mut a = App::new();
        a.tab = Tab::Operator; // `i` composes on the Operator tab (Overview is default now)
        a.update(key('i', KeyModifiers::NONE));
        assert!(a.chat_composing);
        a.update(ev(KeyCode::Esc));
        assert!(!a.chat_composing);
        // After leaving compose, digit keys switch tabs again.
        a.update(key('3', KeyModifiers::NONE));
        assert_eq!(a.tab, Tab::Plans);
        // Ctrl-C quits even while composing (the universal escape hatch).
        let mut b = App::new();
        b.tab = Tab::Operator;
        b.update(key('i', KeyModifiers::NONE));
        assert_eq!(b.update(key('c', KeyModifiers::CONTROL)), Action::Quit);
        assert!(b.should_quit);
        // A plain `q` typed while composing is just text, not quit.
        let mut c = App::new();
        c.tab = Tab::Operator;
        c.update(key('i', KeyModifiers::NONE));
        assert_eq!(c.update(key('q', KeyModifiers::NONE)), Action::Render);
        assert!(!c.should_quit);
        assert_eq!(c.chat_input, "q");
    }

    #[test]
    fn composer_recalls_history_and_takes_a_paste_as_one_edit() {
        fn arrow(code: KeyCode) -> Event {
            Event::Key(KeyEvent::new(code, KeyModifiers::NONE))
        }
        fn send_line(a: &mut App, s: &str) {
            a.chat_input.clear();
            for c in s.chars() {
                a.update(key(c, KeyModifiers::NONE));
            }
            a.update(arrow(KeyCode::Enter));
            let id = a.su_pending_turn.as_ref().unwrap().command_id.clone();
            a.acknowledge_su_turn(&id);
            a.update(Event::ChatDone); // finish the turn so the next Enter is allowed
        }

        let mut a = App::new();
        a.tab = Tab::Operator;
        a.update(key('i', KeyModifiers::NONE)); // enter compose
        assert!(a.chat_composing);

        send_line(&mut a, "first");
        send_line(&mut a, "second");
        assert_eq!(
            a.chat_history,
            vec!["first".to_string(), "second".to_string()]
        );
        assert!(a.chat_input.is_empty());

        // Half-typed work is stashed on the FIRST Up, not destroyed.
        a.chat_input.clear();
        for c in "draft".chars() {
            a.update(key(c, KeyModifiers::NONE));
        }
        a.update(arrow(KeyCode::Up));
        assert_eq!(a.chat_input, "second");
        a.update(arrow(KeyCode::Up));
        assert_eq!(a.chat_input, "first");
        // The oldest entry HOLDS rather than wrapping — a held key must not
        // silently cycle back around to the newest line.
        a.update(arrow(KeyCode::Up));
        assert_eq!(a.chat_input, "first");
        a.update(arrow(KeyCode::Down));
        assert_eq!(a.chat_input, "second");
        // Walking past the newest restores the stashed draft.
        a.update(arrow(KeyCode::Down));
        assert_eq!(a.chat_input, "draft");
        // Down with nothing to recall is inert, never destructive.
        a.update(arrow(KeyCode::Down));
        assert_eq!(a.chat_input, "draft");

        // Editing leaves recall mode, so a later Down cannot overwrite the edit.
        a.update(arrow(KeyCode::Up));
        assert_eq!(a.chat_input, "second");
        a.update(key('!', KeyModifiers::NONE));
        assert_eq!(a.chat_input, "second!");
        a.update(arrow(KeyCode::Down));
        assert_eq!(
            a.chat_input, "second!",
            "Down must not clobber an edited line"
        );

        // THE POINT OF BRACKETED PASTE: multi-line text lands as ONE edit with
        // its newlines intact, and does NOT submit. Before this, each newline
        // arrived as Enter and sent a separate half-message.
        a.chat_input.clear();
        a.update(Event::Paste("alpha\nbeta".into()));
        assert_eq!(a.chat_input, "alpha\nbeta");
        assert!(!a.chat_streaming, "a paste must never submit the turn");
        assert_eq!(a.chat_history.len(), 2, "a paste must not enter history");

        // Re-sending the same line collapses instead of padding the ring.
        send_line(&mut a, "second");
        assert_eq!(
            a.chat_history,
            vec!["first".to_string(), "second".to_string()]
        );
    }

    #[test]
    fn composer_moves_within_multiline_draft_before_recalling_history() {
        fn arrow(code: KeyCode) -> Event {
            Event::Key(KeyEvent::new(code, KeyModifiers::NONE))
        }

        let mut a = App::new();
        a.tab = Tab::Operator;
        a.chat_history.push("previous turn".into());
        a.update(key('i', KeyModifiers::NONE));
        a.update(Event::Paste("first\nsecond".into()));

        // The draft starts on its last logical row. Up moves to that row's
        // same display column, rather than entering history immediately.
        a.update(arrow(KeyCode::Up));
        assert_eq!(a.chat_input, "first\nsecond");
        assert_eq!(a.chat_cursor_line_col(), (0, 5));
        assert!(a.chat_history_idx.is_none());

        // Only a second Up, from the first logical row, may recall history.
        a.update(arrow(KeyCode::Up));
        assert_eq!(a.chat_input, "previous turn");
        assert_eq!(a.chat_history_idx, Some(0));
    }

    /// `Ctrl-Z` — the "undo" half of PUBLIC_RELEASE_UX.md:372's composer
    /// promise ("Unicode bracketed paste, undo/history, and draft
    /// preservation"). History and draft preservation shipped; undo did not,
    /// and a green suite could never reveal that because a missing feature has
    /// no failing test.
    ///
    /// Written to PUI-EDITOR-UNDO's own falsifier — "Undo corrupts Unicode or
    /// loses the pre-paste draft" — so both halves genuinely fail the case.
    #[test]
    fn composer_undo_restores_the_pre_paste_draft_without_corrupting_unicode() {
        fn ctrl_z() -> Event {
            Event::Key(KeyEvent::new(KeyCode::Char('z'), KeyModifiers::CONTROL))
        }

        let mut a = App::new();
        a.tab = Tab::Operator;
        a.update(key('i', KeyModifiers::NONE)); // enter compose
        assert!(a.chat_composing);

        // Deliberately hostile to a byte-indexed undo: multi-byte scalars,
        // a COMBINING acute (so one grapheme spans two scalars), an astral
        // emoji, a regional-indicator flag pair, and RTL text. A restore that
        // does index arithmetic lands mid-grapheme on any of these.
        let draft = "δraft ünsent — e\u{0301}te\u{0301} 🧪🇯🇵 عربى";
        a.chat_input = draft.to_string();

        a.update(Event::Paste("alpha\nbeta\ngamma".into()));
        assert_eq!(
            a.chat_input,
            format!("{draft}alpha\nbeta\ngamma"),
            "the paste must land as one edit with its newlines intact"
        );

        a.update(ctrl_z());
        assert_eq!(
            a.chat_input, draft,
            "undo must restore the pre-paste draft BYTE-EXACTLY"
        );
        assert!(!a.chat_streaming, "undo must never submit the turn");
        // Ctrl-Z must not reach the typing arm: that `match code` ignores
        // modifiers, so an un-intercepted chord appends a literal "z".
        assert!(
            !a.chat_input.ends_with('z'),
            "Ctrl-Z must not type a literal z into the message"
        );

        // An empty undo stack is INERT, never a clear — an undo that wiped the
        // line here would BE the data loss the feature exists to prevent.
        a.update(ctrl_z());
        assert_eq!(
            a.chat_input, draft,
            "undo with nothing to undo must not clear"
        );

        // Successive pastes unwind one at a time, newest first.
        a.update(Event::Paste("one".into()));
        a.update(Event::Paste("two".into()));
        assert_eq!(a.chat_input, format!("{draft}onetwo"));
        a.update(ctrl_z());
        assert_eq!(a.chat_input, format!("{draft}one"));
        a.update(ctrl_z());
        assert_eq!(a.chat_input, draft);
    }

