    #[test]
    fn page_up_triggers_load_earlier_then_prepends() {
        let mut a = App::new();
        a.tab = Tab::Operator; // chat behavior — Overview is the default now (Brief 23)
        a.update(Event::ChatHistory {
            conversation_id: "c1".into(),
            messages: vec![ChatMessage::user("newest")],
            has_more_earlier: true,
            oldest_seq: Some(10),
        });
        // PageUp with more history + a conversation → fires a load + marks in-flight.
        assert_eq!(a.update(ev(KeyCode::PageUp)), Action::LoadEarlierChat);
        assert!(a.chat_loading_earlier);
        // A second PageUp while loading does NOT re-fire (deduped) — just scrolls.
        assert_eq!(a.update(ev(KeyCode::PageUp)), Action::Render);
        // The earlier page prepends before the existing turns + advances the cursor.
        a.update(Event::ChatEarlier {
            messages: vec![
                ChatMessage::user("older-1"),
                ChatMessage::assistant("older-2"),
            ],
            has_more_earlier: false,
            oldest_seq: Some(8),
        });
        assert!(!a.chat_loading_earlier);
        assert!(!a.chat_has_more_earlier);
        assert_eq!(a.chat_oldest_seq, Some(8));
        assert_eq!(a.chat_messages.len(), 3);
        assert_eq!(a.chat_messages[0].content, "older-1"); // prepended at the front
        assert_eq!(a.chat_messages[2].content, "newest");
        // No more history → PageUp no longer fires a load.
        assert_eq!(a.update(ev(KeyCode::PageUp)), Action::Render);
    }

    #[test]
    fn page_up_no_load_without_more_or_conversation() {
        let mut a = App::new();
        a.tab = Tab::Operator; // chat behavior — Overview is the default now (Brief 23)
                               // No conversation loaded yet → PageUp just scrolls.
        assert_eq!(a.update(ev(KeyCode::PageUp)), Action::Render);
        assert!(!a.chat_loading_earlier);
        // Conversation loaded but no earlier history → PageUp just scrolls.
        a.update(Event::ChatHistory {
            conversation_id: "c1".into(),
            messages: vec![ChatMessage::user("only")],
            has_more_earlier: false,
            oldest_seq: Some(0),
        });
        assert_eq!(a.update(ev(KeyCode::PageUp)), Action::Render);
        assert!(!a.chat_loading_earlier);
    }

    // --- Transcript copy contract (P-007, PUBLIC_RELEASE_UX.md:188/:373) ---

    fn chat_app(n: usize) -> App {
        let mut a = App::new();
        a.tab = Tab::Operator;
        a.chat_messages = (0..n)
            .map(|i| ChatMessage::user(&format!("m{i}")))
            .collect();
        a
    }

    // --- change cards (PUBLIC_RELEASE_UX.md:375) -------------------------
    fn edit_call(path: &str) -> crate::models::ChatToolCall {
        crate::models::ChatToolCall {
            name: "capability:edit".into(),
            id: Some("c1".into()),
            needs_approval: false,
            input: Some(serde_json::json!({
                "file_path": path, "old_string": "a\nb\nc", "new_string": "a\nB\nc",
            })),
            result: None,
            outcome: crate::models::ToolOutcome::Ok,
        }
    }

    /// An app whose newest block carries `n` change cards.
    fn card_app(n: usize) -> App {
        let mut a = chat_app(2);
        let last = a.chat_messages.len() - 1;
        a.chat_messages[last].tools = (0..n).map(|i| edit_call(&format!("f{i}.rs"))).collect();
        a
    }

    /// CALIBRATION for the change-card group: with NO explicit cursor, Enter on
    /// the Operator tab must still open the composer. Every other test below
    /// passes identically whether or not expansion quietly stole Enter from the
    /// composer for the (very common) case of a last turn that edited a file —
    /// so this is the one that can catch it.
    #[test]
    fn enter_without_a_cursor_still_opens_the_composer() {
        let mut a = card_app(1);
        a.tab = Tab::Operator;
        assert!(a.chat_focus.is_none(), "precondition: no explicit cursor");
        assert!(
            !a.focused_change_cards().is_empty(),
            "precondition: a change card IS present, so only the cursor gate can save Enter"
        );
        a.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert!(a.chat_composing, "Enter must still open the composer");
        assert!(a.open_change_card.is_none(), "and must not open a diff");
    }

    #[test]
    fn enter_on_a_cursored_block_opens_its_change_card() {
        let mut a = card_app(1);
        a.tab = Tab::Operator;
        a.step_chat_focus(0); // an explicit cursor, without moving it
        a.on_key(KeyCode::Enter, KeyModifiers::NONE);
        let open = a.open_change_card.as_ref().expect("card must open");
        assert_eq!(open.card.path, "f0.rs");
        assert_eq!(open.scroll, 0);
        assert!(
            !a.chat_composing,
            "expansion must not also open the composer"
        );
    }

    #[test]
    fn enter_on_a_cursored_block_with_no_edit_still_opens_the_composer() {
        let mut a = chat_app(2); // no tool calls at all
        a.tab = Tab::Operator;
        a.step_chat_focus(0);
        a.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert!(a.chat_composing);
        assert!(a.open_change_card.is_none());
    }

    #[test]
    fn an_open_card_owns_scroll_and_copy_then_esc_returns_the_transcript() {
        let mut a = card_app(1);
        a.tab = Tab::Operator;
        a.chat_scroll = 0;
        a.step_chat_focus(0);
        a.on_key(KeyCode::Enter, KeyModifiers::NONE);

        a.on_key(KeyCode::Char('j'), KeyModifiers::NONE);
        assert_eq!(a.open_change_card.as_ref().unwrap().scroll, 1);
        assert_eq!(a.chat_scroll, 0, "the transcript behind must not scroll");

        a.on_key(KeyCode::Char('k'), KeyModifiers::NONE);
        assert_eq!(a.open_change_card.as_ref().unwrap().scroll, 0);

        match a.on_key(KeyCode::Char('y'), KeyModifiers::NONE) {
            Action::CopyToClipboard { sequence } => assert!(sequence.contains("\x1b]52;c;")),
            other => panic!("y must copy the open card, got {other:?}"),
        }
        let ack = a
            .toast
            .as_ref()
            .map(|t| t.message.clone())
            .unwrap_or_default();
        assert!(ack.contains("edit card"), "copied the wrong subject: {ack}");

        a.on_key(KeyCode::Esc, KeyModifiers::NONE);
        assert!(a.open_change_card.is_none());
        // Esc closed the card and left the transcript exactly as it was.
        assert_eq!(a.chat_scroll, 0);
        assert!(!a.chat_composing);
    }

    #[test]
    fn shift_y_on_an_open_card_copies_the_raw_payload() {
        let mut a = card_app(1);
        a.tab = Tab::Operator;
        a.step_chat_focus(0);
        a.on_key(KeyCode::Enter, KeyModifiers::NONE);
        a.on_key(KeyCode::Char('Y'), KeyModifiers::NONE);
        let ack = a
            .toast
            .as_ref()
            .map(|t| t.message.clone())
            .unwrap_or_default();
        assert!(ack.starts_with("Copied edit card raw"), "{ack}");
    }

    #[test]
    fn n_and_p_walk_the_other_cards_on_the_same_block_and_reset_scroll() {
        // A turn that edited three files is ONE transcript block; without this
        // the other two are unreachable without closing and re-opening, with no
        // gesture that says which one you get.
        let mut a = card_app(3);
        a.tab = Tab::Operator;
        a.step_chat_focus(0);
        a.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert_eq!(a.open_change_card.as_ref().unwrap().card.path, "f0.rs");

        a.on_key(KeyCode::Char('j'), KeyModifiers::NONE);
        assert_eq!(a.open_change_card.as_ref().unwrap().scroll, 1);
        a.on_key(KeyCode::Char('n'), KeyModifiers::NONE);
        let open = a.open_change_card.as_ref().unwrap();
        assert_eq!(open.card.path, "f1.rs");
        assert_eq!(open.scroll, 0, "a new diff must start at its top");

        a.on_key(KeyCode::Char('n'), KeyModifiers::NONE);
        assert_eq!(a.open_change_card.as_ref().unwrap().card.path, "f2.rs");
        a.on_key(KeyCode::Char('n'), KeyModifiers::NONE);
        assert_eq!(
            a.open_change_card.as_ref().unwrap().card.path,
            "f2.rs",
            "clamps at the last card"
        );
        a.on_key(KeyCode::Char('p'), KeyModifiers::NONE);
        assert_eq!(a.open_change_card.as_ref().unwrap().card.path, "f1.rs");
    }

    #[test]
    fn an_open_card_does_not_trap_keys_it_does_not_claim() {
        // The precedence rule is "owns scroll and copy", NOT "swallows
        // everything" — a modal that traps the tab keys strands the reader.
        let mut a = card_app(1);
        a.tab = Tab::Operator;
        a.step_chat_focus(0);
        a.on_key(KeyCode::Enter, KeyModifiers::NONE);
        assert!(a.open_change_card.is_some());
        a.on_key(KeyCode::Char('2'), KeyModifiers::NONE);
        assert_ne!(a.tab, Tab::Operator, "a tab switch must still get through");
    }

    #[test]
    fn the_open_card_is_a_snapshot_that_streaming_cannot_re_resolve() {
        // The transcript streams and prepends under an open diff; re-resolving
        // the card from a live index would swap the file out mid-scroll.
        let mut a = card_app(1);
        a.tab = Tab::Operator;
        a.step_chat_focus(0);
        a.on_key(KeyCode::Enter, KeyModifiers::NONE);
        let before = a.open_change_card.clone().unwrap();

        a.chat_messages.insert(
            0,
            crate::models::ChatMessage::user("an earlier turn arrived"),
        );
        a.chat_messages
            .push(crate::models::ChatMessage::assistant("and a newer one"));

        assert_eq!(
            a.open_change_card.as_ref().unwrap().card,
            before.card,
            "the open diff must not change identity underneath the reader"
        );
    }

    /// CALIBRATION for the whole group below: `j`/`k` must remain the transcript's
    /// line-wise scroll. Every other test here would pass just as happily if the
    /// copy cursor had been bolted onto `j`/`k` and silently broken the shipped
    /// navigation PUBLIC_RELEASE_UX.md:373 specifies, so this is the test that
    /// can actually catch that.
    #[test]
    fn copy_cursor_does_not_steal_the_j_k_transcript_scroll() {
        let mut a = chat_app(3);
        a.chat_scroll = 0;
        a.update(ev(KeyCode::Char('k')));
        assert_eq!(
            a.chat_scroll, 1,
            "k must still scroll one line into history"
        );
        a.update(ev(KeyCode::Char('j')));
        assert_eq!(
            a.chat_scroll, 0,
            "j must still scroll one line toward latest"
        );
        assert_eq!(
            a.chat_focus, None,
            "scrolling must not set the copy cursor — they are separate gestures"
        );
    }

    #[test]
    fn y_copies_the_newest_block_with_no_focus_set() {
        let mut a = chat_app(3);
        match a.update(ev(KeyCode::Char('y'))) {
            Action::CopyToClipboard { sequence } => {
                // OSC 52 clipboard write, base64 payload.
                assert!(sequence.starts_with("\x1b]52;c;"), "got {sequence:?}");
            }
            other => panic!("expected a clipboard write, got {other:?}"),
        }
        let toast = a.toast.as_ref().expect("copy must acknowledge");
        assert!(toast.message.starts_with("Copied "), "{}", toast.message);
    }

    /// "Copy success is acknowledged without moving selection."
    #[test]
    fn y_acknowledges_without_moving_the_selection() {
        let mut a = chat_app(4);
        a.chat_focus = Some(1);
        a.update(ev(KeyCode::Char('y')));
        assert_eq!(a.chat_focus, Some(1));
        a.update(ev(KeyCode::Char('Y')));
        assert_eq!(a.chat_focus, Some(1));
    }

    /// Shift-Y on a block with no payload must SAY so — never quietly fall back
    /// to the rendered form, which would hand the user different bytes than the
    /// key they pressed promises.
    #[test]
    fn shift_y_without_a_raw_payload_refuses_instead_of_copying_rendered() {
        let mut a = chat_app(1);
        let action = a.update(ev(KeyCode::Char('Y')));
        assert!(
            matches!(action, Action::Render),
            "no clipboard write is owed, got {action:?}"
        );
        let toast = a.toast.as_ref().expect("must acknowledge the refusal");
        assert!(
            toast.message.contains("No raw payload"),
            "{}",
            toast.message
        );
    }

    #[test]
    fn brace_keys_step_the_focus_and_clamp_at_both_ends() {
        let mut a = chat_app(3);
        // Focus resolves to the newest (index 2) before the first explicit move.
        a.update(ev(KeyCode::Char('{')));
        assert_eq!(a.chat_focus, Some(1));
        a.update(ev(KeyCode::Char('{')));
        assert_eq!(a.chat_focus, Some(0));
        a.update(ev(KeyCode::Char('{')));
        assert_eq!(a.chat_focus, Some(0), "clamps at the oldest block");
        for _ in 0..5 {
            a.update(ev(KeyCode::Char('}')));
        }
        assert_eq!(a.chat_focus, Some(2), "clamps at the newest block");
    }

    /// Prepending history renumbers every block, so the focus must ride along or
    /// `y` would copy a different message than the one that is marked.
    #[test]
    fn loading_earlier_history_keeps_the_focus_on_the_same_block() {
        let mut a = chat_app(2);
        a.chat_focus = Some(0);
        let focused_before = a.chat_messages[0].content.clone();
        a.prepend_chat_earlier(
            vec![ChatMessage::user("older-a"), ChatMessage::user("older-b")],
            false,
            None,
        );
        assert_eq!(a.chat_focus, Some(2), "shifted by the page size");
        assert_eq!(
            a.chat_messages[a.effective_chat_focus().unwrap()].content,
            focused_before,
            "the SAME block stays focused after the renumber"
        );
    }

    /// A focus stranded past the end by a reload degrades to the newest block
    /// rather than copying nothing.
    #[test]
    fn out_of_range_focus_falls_back_to_the_newest_block() {
        let mut a = chat_app(2);
        a.chat_focus = Some(99);
        assert_eq!(a.effective_chat_focus(), Some(1));
        let mut empty = chat_app(0);
        empty.chat_focus = Some(3);
        assert_eq!(empty.effective_chat_focus(), None);
    }

    #[test]
    fn chat_history_for_send_excludes_streaming_and_empty() {
        let mut a = App::new();
        a.chat_messages = vec![ChatMessage::user("q1"), ChatMessage::assistant("a1")];
        a.begin_user_send("q2"); // pushes user q2 + an empty streaming bubble
        let h = a.chat_history_for_send();
        assert_eq!(
            h,
            vec![
                ("user".to_string(), "q1".to_string()),
                ("assistant".to_string(), "a1".to_string()),
                ("user".to_string(), "q2".to_string()),
            ]
        );
    }

    #[test]
    fn chat_scroll_keys_adjust_offset_and_delta_snaps_bottom() {
        let mut a = App::new();
        a.tab = Tab::Operator; // chat behavior — Overview is the default now (Brief 23)
        assert_eq!(a.chat_scroll, 0);
        a.update(ev(KeyCode::Char('k'))); // up into history
        a.update(ev(KeyCode::Char('k')));
        assert_eq!(a.chat_scroll, 2);
        a.update(ev(KeyCode::PageUp));
        assert_eq!(a.chat_scroll, 12);
        a.update(ev(KeyCode::Char('j'))); // toward latest
        assert_eq!(a.chat_scroll, 11);
        a.update(ev(KeyCode::PageDown));
        assert_eq!(a.chat_scroll, 1);
        // A new delta snaps back to the bottom.
        a.begin_user_send("x");
        a.chat_scroll = 5;
        a.update(Event::ChatDelta("y".into()));
        assert_eq!(a.chat_scroll, 0);
    }

    #[test]
    fn open_chat_and_focus_pane_intents() {
        let mut a = App::new();
        a.update(key('3', KeyModifiers::NONE));
        assert_eq!(a.tab, Tab::Plans);
        // open_chat focuses the operator pane.
        a.apply_intent("open_chat", &serde_json::json!({})).unwrap();
        assert_eq!(a.tab, Tab::Operator);
        // focus_pane → a FocusPane action (companion side-effect, run-loop driven).
        match a.update(Event::TuiIntent {
            id: 9,
            intent: "focus_pane".into(),
            args: serde_json::json!({ "pane_id": 7 }),
        }) {
            Action::FocusPane { intent_id, pane_id } => {
                assert_eq!(intent_id, 9);
                assert_eq!(pane_id, 7);
            }
            other => panic!("expected FocusPane, got {other:?}"),
        }
        // Missing pane_id → an error IntentResult, not a panic.
        match a.update(Event::TuiIntent {
            id: 10,
            intent: "focus_pane".into(),
            args: serde_json::json!({}),
        }) {
            Action::IntentResult { id, error, .. } => {
                assert_eq!(id, 10);
                assert!(error.is_some());
            }
            other => panic!("expected IntentResult error, got {other:?}"),
        }
    }

    // --- Memory tab (D-006 Step 2, pui-completion-and-polish) ---

    fn mem(id: &str, text: &str, kind: &str) -> crate::models::MemoryEntry {
        crate::models::MemoryEntry {
            id: id.into(),
            memory: text.into(),
            metadata: Some(serde_json::json!({ "kind": kind })),
            score: None,
        }
    }

    #[test]
    fn memory_load_state_distinguishes_backend_auth_and_transport_failures() {
        let mut a = App::new();

        a.update(Event::MemoryLoad(MemoryLoadState::BackendUnavailable {
            reason: Some("mem0 disabled".into()),
        }));
        assert!(!a.memory_available);
        assert!(matches!(
            a.memory_load_state,
            MemoryLoadState::BackendUnavailable { .. }
        ));

        a.update(Event::MemoryLoad(MemoryLoadState::AuthFailure {
            message: "401 principal required".into(),
        }));
        assert!(!a.memory_available);
        assert!(a.memories.is_empty());
        assert!(matches!(
            a.memory_load_state,
            MemoryLoadState::AuthFailure { .. }
        ));

        a.update(Event::MemoryLoad(MemoryLoadState::TransportFailure {
            message: "connection refused".into(),
        }));
        assert!(!a.memory_available);
        assert!(matches!(
            a.memory_load_state,
            MemoryLoadState::TransportFailure { .. }
        ));

        a.update(Event::MemoryLoad(MemoryLoadState::Available {
            results: vec![mem("m1", "likes rust", "preference")],
        }));
        assert!(a.memory_available);
        assert_eq!(a.memories.len(), 1);
    }

    #[test]
    fn memory_tab_lists_searches_and_clears() {
        let mut a = App::new();
        // `m` is the model picker while Agent Chat owns focus; from another
        // tab it remains the stable Memory-tab shortcut.
        a.tab = Tab::Overview;
        a.update(key('m', KeyModifiers::NONE));
        assert_eq!(a.tab, Tab::Memory);
        // The list lands from memory:list; availability follows the payload.
        a.update(Event::MemoryLoad(MemoryLoadState::Available {
            results: vec![
                mem("m1", "likes rust", "preference"),
                mem("m2", "tz is ET", "identity"),
            ],
        }));
        assert!(a.memory_available);
        assert_eq!(a.visible_memories().len(), 2);
        a.update(key('j', KeyModifiers::NONE));
        assert_eq!(a.memory_sel, 1);
        assert_eq!(a.selected_memory().unwrap().id, "m2");
        // `/` opens the composer; typed keys go to the query, not tabs.
        a.update(key('/', KeyModifiers::NONE));
        assert!(a.memory_search_open);
        a.update(key('r', KeyModifiers::NONE));
        a.update(key('u', KeyModifiers::NONE));
        a.update(key('s', KeyModifiers::NONE));
        a.update(key('t', KeyModifiers::NONE));
        assert_eq!(a.memory_search_input, "rust");
        assert_eq!(a.tab, Tab::Memory);
        // Enter fires the search + arms the active query.
        match a.update(ev(KeyCode::Enter)) {
            Action::SearchMemory { query, harness } => {
                assert_eq!(query, "rust");
                assert_eq!(harness, "papercup");
            }
            other => panic!("expected SearchMemory, got {other:?}"),
        }
        assert!(!a.memory_search_open);
        // Hits for the ACTIVE query apply; a stale query's hits are dropped.
        a.update(Event::MemoryHits {
            query: "stale".into(),
            results: vec![mem("x", "x", "project")],
        });
        assert!(a.visible_memories().is_empty()); // armed query, no hits yet
        a.update(Event::MemoryHits {
            query: "rust".into(),
            results: vec![mem("m1", "likes rust", "preference")],
        });
        assert_eq!(a.visible_memories().len(), 1);
        assert_eq!(a.selected_memory().unwrap().kind(), "preference");
        // Esc clears the search back to the full list.
        a.update(ev(KeyCode::Esc));
        assert!(a.memory_hits.is_none());
        assert_eq!(a.visible_memories().len(), 2);
        // Esc with no active search just dismisses toasts (no panic).
        a.update(ev(KeyCode::Esc));
    }

    #[test]
    fn memory_search_esc_cancels_composer() {
        let mut a = App::new();
        a.update(key('m', KeyModifiers::NONE));
        a.update(key('/', KeyModifiers::NONE));
        a.update(key('x', KeyModifiers::NONE));
        a.update(ev(KeyCode::Esc));
        assert!(!a.memory_search_open);
        assert!(a.memory_search_input.is_empty());
        assert!(a.memory_hits.is_none());
        // An empty query on Enter is inert.
        a.update(key('/', KeyModifiers::NONE));
        assert_eq!(a.update(ev(KeyCode::Enter)), Action::Render);
        assert!(a.memory_hits.is_none());
    }

    // --- POTS scope axis + picker (D-003, pui-completion-and-polish) ---

    fn plan_in(slug: &str, harness: Option<&str>) -> PlanSummary {
        let mut p = plan(slug);
        p.harness = harness.map(|s| s.to_string());
        p
    }

    #[test]
    fn scope_filters_plans_and_keeps_unattributed_rows() {
        let mut a = App::new();
        assert!(a.all_pots); // fresh installs land in All-Pots
        a.set_plans(vec![
            plan_in("p-papercup", Some("papercup")),
            plan_in("p-restart", Some("restart")),
            plan_in("p-unattributed", None),
        ]);
        assert_eq!(a.visible_plans().len(), 3);
        // Narrow to the active pot (papercup): restart's plan filters out, the
        // unattributed plan stays (it can't be attributed).
        a.all_pots = false;
        let vis: Vec<&str> = a.visible_plans().iter().map(|p| p.slug.as_str()).collect();
        assert_eq!(vis, vec!["p-papercup", "p-unattributed"]);
        // The selection indexes the VISIBLE list.
        a.plan_sel = 1;
        assert_eq!(a.selected_plan().unwrap().slug, "p-unattributed");
        // Scope label follows the axis.
        assert_eq!(a.scope_label(), "⊙ papercup");
        a.all_pots = true;
        assert_eq!(a.scope_label(), "⊙ all pots");
    }

    #[test]
    fn pot_picker_opens_navigates_and_applies() {
        use crate::models::HarnessRef;
        let mut a = App::new();
        a.set_harnesses(vec![
            HarnessRef {
                slug: "papercup".into(),
                path: None,
            },
            HarnessRef {
                slug: "restart".into(),
                path: None,
            },
        ]);
        // `P` opens the picker with the cursor on the current choice (All).
        a.update(key('P', KeyModifiers::SHIFT));
        assert!(a.pot_picker_open);
        assert_eq!(a.pot_picker_sel, 0);
        // j to "papercup", j to "restart", Enter applies pot scope + switches.
        a.update(key('j', KeyModifiers::NONE));
        a.update(key('j', KeyModifiers::NONE));
        a.update(key('j', KeyModifiers::NONE)); // clamped at the last entry
        assert_eq!(a.pot_picker_sel, 2);
        a.update(Event::Key(KeyEvent::new(
            KeyCode::Enter,
            KeyModifiers::NONE,
        )));
        assert!(!a.pot_picker_open);
        assert!(!a.all_pots);
        assert_eq!(a.harness, "restart");
        assert_eq!(*a.active_harness.lock().unwrap(), "restart");
        // Re-open: the cursor sits on the active pot; Enter on "All Pots" widens.
        a.update(key('P', KeyModifiers::SHIFT));
        assert_eq!(a.pot_picker_sel, 2); // index 1 + harness_sel(1)
        a.update(key('k', KeyModifiers::NONE));
        a.update(key('k', KeyModifiers::NONE));
        a.update(Event::Key(KeyEvent::new(
            KeyCode::Enter,
            KeyModifiers::NONE,
        )));
        assert!(a.all_pots);
        assert_eq!(a.harness, "restart"); // the slug axis is untouched by All
                                          // Esc closes without applying.
        a.update(key('P', KeyModifiers::SHIFT));
        a.update(key('j', KeyModifiers::NONE));
        a.update(Event::Key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)));
        assert!(!a.pot_picker_open);
        assert!(a.all_pots); // unchanged
    }

    #[test]
    fn scope_persists_in_view_state_and_snapshot() {
        let mut a = App::new();
        a.all_pots = false;
        let vs = a.capture_view_state();
        assert_eq!(vs.scope.as_deref(), Some("pot"));
        let mut b = App::new();
        assert!(b.all_pots);
        b.apply_view_state(&vs);
        assert!(!b.all_pots);
        // An older snapshot without the field keeps the default.
        let mut c = App::new();
        c.apply_view_state(&ViewState::default());
        assert!(c.all_pots);
        // The agent-facing snapshot exposes the axis.
        assert_eq!(a.state_snapshot()["scope"], "pot");
        assert_eq!(c.state_snapshot()["scope"], "all");
    }

    #[test]
    fn scope_change_clamps_filtered_selection() {
        let mut a = App::new();
        a.set_plans(vec![
            plan_in("p1", Some("restart")),
            plan_in("p2", Some("restart")),
            plan_in("p3", Some("papercup")),
        ]);
        a.plan_sel = 2; // p3 visible under All
                        // Narrowing to papercup leaves 1 visible plan → the cursor clamps.
        a.apply_pot_choice(0); // All (no-op scope-wise but exercises the path)
        assert!(a.all_pots);
        a.all_pots = false;
        a.clamp_scope_sel();
        assert_eq!(a.plan_sel, 0);
        assert_eq!(a.selected_plan().unwrap().slug, "p3");
    }

    // --- Testing run-on-click (D-004a, pui-completion-and-polish-2026-06-05) ---

    fn test_domain(id: &str) -> TestingDomain {
        TestingDomain {
            id: id.into(),
            label: id.into(),
            description: "d".into(),
            tier: "universal".into(),
        }
    }

    #[test]
    fn testing_enter_fetches_domain_files_then_runs() {
        let mut a = App::new();
        a.update(key('7', KeyModifiers::NONE)); // Testing
        a.set_testing(vec![test_domain("unit"), test_domain("e2e")]);
        a.pane_entered = true; // inside the panes → Enter activates / ↑↓ move within
                               // Enter on the domain column fetches the selected domain's files.
        match a.update(ev(KeyCode::Enter)) {
            Action::FetchTestingFiles { harness, domain_id } => {
                assert_eq!(harness, "papercup");
                assert_eq!(domain_id, "unit");
            }
            other => panic!("expected FetchTestingFiles, got {other:?}"),
        }
        assert!(a.testing_files_loading);
        // Files for the selected domain land + focus hops to the file column.
        a.update(Event::TestingFiles {
            domain_id: "unit".into(),
            files: vec!["a.test.ts".into(), "b.test.ts".into()],
        });
        assert!(!a.testing_files_loading);
        assert_eq!(a.testing_focus, TestingFocus::Files);
        assert_eq!(a.testing_files.len(), 2);
        // j moves the FILE cursor while the file column is focused.
        a.update(key('j', KeyModifiers::NONE));
        assert_eq!(a.testing_file_sel, 1);
        // Enter runs the selected file (marks the run in flight).
        match a.update(ev(KeyCode::Enter)) {
            Action::RunTest { harness, file } => {
                assert_eq!(harness, "papercup");
                assert_eq!(file, "b.test.ts");
            }
            other => panic!("expected RunTest, got {other:?}"),
        }
        assert!(a.test_run.as_ref().unwrap().running);
        // A second Enter while running is inert (one run at a time).
        assert_eq!(a.update(ev(KeyCode::Enter)), Action::Render);
        // The result finalizes the run pane.
        a.update(Event::TestRunDone {
            file: "b.test.ts".into(),
            result: crate::models::TestRunResult {
                status: "pass".into(),
                output: "1 passed".into(),
                ..Default::default()
            },
        });
        let run = a.test_run.as_ref().unwrap();
        assert!(!run.running);
        assert_eq!(run.status, "pass");
        assert_eq!(run.output, "1 passed");
    }

    #[test]
    fn testing_files_stale_guard_and_domain_change_clears() {
        let mut a = App::new();
        a.update(key('7', KeyModifiers::NONE));
        a.set_testing(vec![test_domain("unit"), test_domain("e2e")]);
        a.pane_entered = true; // inside the panes → ↑/↓ move within (Tab still switches)
                               // A stale fetch for a NON-selected domain is dropped.
        a.update(key('j', KeyModifiers::NONE)); // select e2e
        a.update(Event::TestingFiles {
            domain_id: "unit".into(),
            files: vec!["a.test.ts".into()],
        });
        assert!(a.testing_files.is_empty());
        assert_eq!(a.testing_focus, TestingFocus::Domains);
        // A matching fetch applies + focuses the file column.
        a.update(Event::TestingFiles {
            domain_id: "e2e".into(),
            files: vec!["x.spec.ts".into()],
        });
        assert_eq!(a.testing_files.len(), 1);
        assert_eq!(a.testing_focus, TestingFocus::Files);
        // Tab hops back to the domain column; changing the domain clears the
        // (now stale) file list.
        a.update(ev(KeyCode::Tab));
        assert_eq!(a.testing_focus, TestingFocus::Domains);
        a.update(key('k', KeyModifiers::NONE)); // back to unit
        assert!(a.testing_files.is_empty());
    }

    #[test]
    fn testing_r_runs_only_on_file_column() {
        let mut a = App::new();
        a.update(key('7', KeyModifiers::NONE));
        a.set_testing(vec![test_domain("unit")]);
        // On the domain column `r` is not a run key (and no relaunch armed).
        assert_eq!(a.update(key('r', KeyModifiers::NONE)), Action::None);
        a.update(Event::TestingFiles {
            domain_id: "unit".into(),
            files: vec!["a.test.ts".into()],
        });
        match a.update(key('r', KeyModifiers::NONE)) {
            Action::RunTest { file, .. } => assert_eq!(file, "a.test.ts"),
            other => panic!("expected RunTest, got {other:?}"),
        }
        // An error result still resolves the pane (status from exit fallback).
        a.update(Event::TestRunDone {
            file: "a.test.ts".into(),
            result: crate::models::TestRunResult {
                status: String::new(),
                exit_code: 1,
                output: "boom".into(),
                ..Default::default()
            },
        });
        let run = a.test_run.as_ref().unwrap();
        assert_eq!(run.status, "exit 1");
        assert!(!run.running);
    }

    #[test]
    fn testing_detached_progress_binds_run_id_and_drops_stale_polls() {
        let mut a = App::new();
        a.update(key('7', KeyModifiers::NONE));
        a.set_testing(vec![test_domain("unit")]);
        a.testing_focus = TestingFocus::Files;
        a.testing_files = vec!["a.test.ts".into()];
        a.pane_entered = true;
        assert!(matches!(
            a.update(ev(KeyCode::Enter)),
            Action::RunTest { .. }
        ));

        let snapshot = |run_id: &str, status: &str, output: &str| crate::models::TestRunSnapshot {
            run_id: run_id.into(),
            file_path: Some("a.test.ts".into()),
            status: status.into(),
            output: output.into(),
            ..Default::default()
        };
        a.update(Event::TestRunProgress {
            file: "a.test.ts".into(),
            snapshot: snapshot("run-1", "running", "first chunk"),
        });
        let run = a.test_run.as_ref().unwrap();
        assert_eq!(run.run_id.as_deref(), Some("run-1"));
        assert!(run.running);
        assert_eq!(run.output, "first chunk");

        // A late response from another run cannot overwrite the active pane.
        a.update(Event::TestRunProgress {
            file: "a.test.ts".into(),
            snapshot: snapshot("run-old", "fail", "stale"),
        });
        let run = a.test_run.as_ref().unwrap();
        assert_eq!(run.run_id.as_deref(), Some("run-1"));
        assert!(run.running);
        assert_eq!(run.output, "first chunk");

        a.update(Event::TestRunProgress {
            file: "a.test.ts".into(),
            snapshot: snapshot("run-1", "cancelled", "cancelled by user"),
        });
        let run = a.test_run.as_ref().unwrap();
        assert!(!run.running);
        assert_eq!(run.status, "cancelled");
        assert!(!run.cancelling);
    }

    #[test]
    fn testing_esc_requests_cancel_without_leaving_the_pane() {
        let mut a = App::new();
        a.update(key('7', KeyModifiers::NONE));
        a.set_testing(vec![test_domain("unit")]);
        a.testing_focus = TestingFocus::Files;
        a.testing_files = vec!["a.test.ts".into()];
        a.pane_entered = true;
        assert!(matches!(
            a.update(ev(KeyCode::Enter)),
            Action::RunTest { .. }
        ));
        a.update(Event::TestRunProgress {
            file: "a.test.ts".into(),
            snapshot: crate::models::TestRunSnapshot {
                run_id: "run-cancel".into(),
                status: "running".into(),
                ..Default::default()
            },
        });

        match a.update(ev(KeyCode::Esc)) {
            Action::CancelTest {
                harness,
                run_id,
                file,
            } => {
                assert_eq!(harness, "papercup");
                assert_eq!(run_id, "run-cancel");
                assert_eq!(file, "a.test.ts");
            }
            other => panic!("expected CancelTest, got {other:?}"),
        }
        assert!(a.pane_entered);
        assert!(a.test_run.as_ref().unwrap().cancelling);
        assert_eq!(a.test_run.as_ref().unwrap().status, "cancelling");
    }

