    #[test]
    fn plans_tab_two_level_nav_list_and_items_with_detail() {
        // Owner ask 2026-06-16: the Plans tab gains Colony-style two-level nav —
        // ←/→ switch the plans-list ↔ work-items panes, Enter drills in, ↑/↓ move
        // within, Enter opens that row's detail popup, Esc steps back out.
        use crate::app::PlansFocus;
        let mut a = App::new();
        a.tab = Tab::Plans;
        let mut p1 = plan("plan-x");
        p1.item_counts = crate::models::ItemCounts {
            todo: 2,
            done: 1,
            ..Default::default()
        };
        a.set_plans(vec![p1, plan("plan-y")]);
        a.plan_item_states = Some(item_states("plan-x", &["P-001", "P-002", "P-003"]));
        assert!(!a.plans_entered);
        assert_eq!(a.plans_focus, PlansFocus::List);
        // Enter drills into the focused (list) pane — no popup yet.
        a.update(ev(KeyCode::Enter));
        assert!(a.plans_entered);
        assert!(!a.fleet_detail_open);
        // Inside the list: ↓ moves the plan selection.
        a.update(ev(KeyCode::Char('j')));
        assert_eq!(a.plan_sel, 1);
        assert_eq!(a.selected_plan().unwrap().slug, "plan-y");
        // ←/→ (arrow-only on the in-app tab — `h` stays Overview) switches to the
        // work-items pane at any level.
        a.update(ev(KeyCode::Right));
        assert_eq!(a.plans_focus, PlansFocus::Items);
        // Re-select plan-x to get its loaded items.
        a.update(ev(KeyCode::Left)); // back to list
        a.update(ev(KeyCode::Char('k'))); // plan_sel → 0 (plan-x)
        assert_eq!(a.plan_sel, 0);
        a.plan_item_states = Some(item_states("plan-x", &["P-001", "P-002", "P-003"]));
        a.update(ev(KeyCode::Right)); // → Items
        assert_eq!(a.plans_focus, PlansFocus::Items);
        a.update(ev(KeyCode::Char('j')));
        assert_eq!(a.plan_items_sel, 1);
        a.update(ev(KeyCode::Char('j')));
        assert_eq!(a.plan_items_sel, 2);
        a.update(ev(KeyCode::Char('j'))); // clamp at the last item
        assert_eq!(a.plan_items_sel, 2);
        // Enter opens the work-item detail popup; j steps within it.
        a.update(ev(KeyCode::Enter));
        assert!(a.fleet_detail_open);
        assert_eq!(a.selected_plan_item().unwrap().item_id, "P-003");
        a.update(ev(KeyCode::Char('k')));
        assert_eq!(a.plan_items_sel, 1);
        a.update(ev(KeyCode::Esc)); // close popup
        assert!(!a.fleet_detail_open);
        // Esc steps out of the entered pane back to browsing.
        a.update(ev(KeyCode::Esc));
        assert!(!a.plans_entered);
    }

    #[test]
    fn context_task_selection_routes_promote_through_the_agent_chat_bridge() {
        use crate::agent_chats::AgentChatTaskAction;
        use crate::models::{
            ConversationContextCapabilities, ConversationContextFrame,
            ConversationContextProjection, ConversationContextProjectionTarget,
            ConversationContextSession,
        };

        // `pui context-pane agent_chat chat-1 papercusp`: an explicit target.
        let mut app = App::new();
        app.pinned = Some(Tab::PlansBoard);
        app.tab = Tab::PlansBoard;
        app.context_projection_target_explicit = true;
        app.context_projection_target = Some(ConversationContextProjectionTarget::new(
            "agent_chat",
            "chat-1",
            Some("papercusp".into()),
        ));
        app.context_projection = Some(ConversationContextProjection {
            schema_version: "conversation-context-v1".into(),
            session: ConversationContextSession {
                source_kind: "agent_chat".into(),
                session_id: "chat-1".into(),
                harness: Some("papercusp".into()),
                role: Some("sentinel".into()),
                linked_work_item_id: None,
                capability_tier: "owned-loop".into(),
            },
            capabilities: ConversationContextCapabilities {
                live_frames: true,
                task_write: true,
                approval_write: true,
            },
            frames: vec![
                ConversationContextFrame::Task {
                    id: "task:first".into(),
                    task_id: "first".into(),
                    content: "First".into(),
                    active_form: "Doing first".into(),
                    status: "pending".into(),
                    blocker_ref: None,
                    explanation: None,
                    position: 0,
                    updated_at: "now".into(),
                    links: vec![],
                },
                ConversationContextFrame::Task {
                    id: "task:second".into(),
                    task_id: "second".into(),
                    content: "Second".into(),
                    active_form: "Doing second".into(),
                    status: "pending".into(),
                    blocker_ref: None,
                    explanation: None,
                    position: 1,
                    updated_at: "now".into(),
                    links: vec![],
                },
            ],
        });

        assert_eq!(app.update(ev(KeyCode::Char('j'))), Action::Render);
        assert_eq!(app.context_task_sel, 1);
        assert_eq!(
            app.update(ev(KeyCode::Char('P'))),
            Action::MutateAgentChatTask {
                harness: "papercusp".into(),
                chat_id: "chat-1".into(),
                mutation: crate::agent_chats::AgentChatTaskMutation {
                    action: AgentChatTaskAction::Promote,
                    task_id: Some("second".into()),
                    content: None,
                    active_form: None,
                    blocker_ref: None,
                    expected_updated_at: Some("now".into()),
                    explanation: None,
                },
            }
        );
        app.context_task_pending = false;

        app.context_projection
            .as_mut()
            .unwrap()
            .capabilities
            .task_write = false;
        assert_eq!(app.update(ev(KeyCode::Enter)), Action::None);
    }

    #[test]
    fn context_task_editor_keeps_the_exact_draft_across_a_rejected_edit() {
        use crate::models::{
            ConversationContextCapabilities, ConversationContextFrame,
            ConversationContextProjection, ConversationContextProjectionTarget,
            ConversationContextSession,
        };

        // `pui context-pane agent_chat chat-1 papercusp`: an explicit target.
        let mut app = App::new();
        app.pinned = Some(Tab::PlansBoard);
        app.tab = Tab::PlansBoard;
        app.context_projection_target_explicit = true;
        let target = ConversationContextProjectionTarget::new(
            "agent_chat",
            "chat-1",
            Some("papercusp".into()),
        );
        app.context_projection_target = Some(target.clone());
        app.context_projection = Some(ConversationContextProjection {
            schema_version: "conversation-context-v1".into(),
            session: ConversationContextSession {
                source_kind: "agent_chat".into(),
                session_id: "chat-1".into(),
                harness: Some("papercusp".into()),
                role: Some("sentinel".into()),
                linked_work_item_id: None,
                capability_tier: "owned-loop".into(),
            },
            capabilities: ConversationContextCapabilities {
                live_frames: true,
                task_write: true,
                approval_write: true,
            },
            frames: vec![ConversationContextFrame::Task {
                id: "task:first".into(),
                task_id: "first".into(),
                content: "Original".into(),
                active_form: "Doing original".into(),
                status: "pending".into(),
                blocker_ref: None,
                explanation: None,
                position: 0,
                updated_at: "revision-1".into(),
                links: vec![],
            }],
        });

        assert_eq!(app.update(ev(KeyCode::Char('e'))), Action::Render);
        for _ in 0.."Original".len() {
            app.update(ev(KeyCode::Backspace));
        }
        app.update(Event::Paste("Owner's exact revision".into()));
        let action = app.update(ev(KeyCode::Enter));
        assert!(matches!(action, Action::MutateAgentChatTask { .. }));
        assert!(app.context_task_pending);
        app.update(Event::AgentChatTaskMutationFinished {
            target,
            result: Err("task_revision_conflict".into()),
        });
        assert!(!app.context_task_pending);
        assert_eq!(
            app.context_task_editor
                .as_ref()
                .map(|editor| editor.input.as_str()),
            Some("Owner's exact revision")
        );
        assert!(app
            .last_error
            .as_deref()
            .unwrap()
            .contains("task_revision_conflict"));
    }

    #[test]
    fn plan_progress_enter_opens_detail_popup_and_steps_plans() {
        use crate::fleet::FleetPanel;
        let mut a = App::new();
        a.tab = Tab::Fleet; // default (comms-off) view
        let mut p1 = plan("plan-alpha");
        p1.item_counts = crate::models::ItemCounts {
            todo: 3,
            done: 2,
            ..Default::default()
        };
        let mut p2 = plan("plan-beta");
        p2.item_counts = crate::models::ItemCounts {
            todo: 1,
            wip: 1,
            ..Default::default()
        };
        a.set_plans(vec![p1, p2]);
        a.fleet.entered = true; // inside the panes → ←/→ switch, ⏎ opens, ↑/↓ within
                                // Cycle focus to the plan-progress panel (Roster → Dossier → PlanProgress).
        a.update(ev(KeyCode::Char('l')));
        a.update(ev(KeyCode::Char('l')));
        assert_eq!(a.fleet.fleet_focus, FleetPanel::PlanProgress);
        // Enter opens the detail popup for the highlighted plan.
        assert!(!a.fleet_detail_open);
        a.update(ev(KeyCode::Enter));
        assert!(a.fleet_detail_open);
        // The popup body describes the selected plan (sel 0 → most remaining first).
        let body: String = crate::fleet::plan_detail_lines(&a)
            .iter()
            .flat_map(|l| l.spans.iter())
            .map(|s| s.content.as_ref())
            .collect();
        assert!(
            body.contains("plan-alpha"),
            "popup should name the selected plan: {body}"
        );
        // Modal: j steps to the next plan WITHIN the popup; an unrelated key is
        // swallowed (can't drive the dock underneath).
        a.update(ev(KeyCode::Char('j')));
        assert_eq!(a.fleet.plan_progress_sel, 1);
        a.update(ev(KeyCode::Char('x')));
        assert!(a.fleet_detail_open);
        // Esc closes it.
        a.update(ev(KeyCode::Esc));
        assert!(!a.fleet_detail_open);
    }

